          <div className="flex items-start space-x-3">
             <div className="text-2xl">🍷</div>
             <div>
               <h5 className="font-bold text-luxury-gold text-sm mb-1">Sommelier AI Suggestion</h5>
               <p className="text-sm text-gray-300">
                 Since you ordered <strong>{pairingSuggestion.for}</strong>: <br/>
                 {pairingLoading ? 'Thinking...' : pairingSuggestion.text}
