           <p className="text-xs text-gray-500 mt-2">No equipment needed. Focus on bodyweight, yoga, and mobility.</p>
        </button>

        <button 
          onClick={() => setLocation('Gym')}
          className={`relative p-8 rounded-2xl border-2 transition-all duration-300 text-left overflow-hidden group ${location === 'Gym' ? 'border-luxury-gold bg-luxury-gold/10' : 'border-gray-700 hover:border-gray-500'}`}
        >
           <div className="absolute top-0 right-0 p-4 opacity-20 text-6xl group-hover:scale-110 transition-transform">🏋️</div>
           <h3 className="text-2xl font-serif mb-2">Performance Center</h3>
