import { GoogleGenAI, Modality, Type } from "@google/genai";
import { MENU_ITEMS, SYSTEM_INSTRUCTION_CONCIERGE, SYSTEM_INSTRUCTION_FITNESS, SYSTEM_INSTRUCTION_NUTRITION } from "../constants";
import { UserProfile } from "../types";

// NOTE: In a production app, this should be a backend call to hide the key.
// For this demo, we assume the environment variable is available.
const API_KEY = process.env.API_KEY || ''; 

// Helper to get fresh client (useful for Veo key updates)
const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY || API_KEY });

// 1. AI Nutritionist Recommendation
export const getNutritionRecommendation = async (user: UserProfile) => {
  try {
    const ai = getAiClient();
    const menuContext = JSON.stringify(MENU_ITEMS.map(item => ({
      name: item.name,
      description: item.description,
      calories: item.calories,
      tags: item.tags,
      id: item.id
    })));

    const prompt = `
      Guest Profile:
      Name: ${user.name}
      Goal: ${user.healthGoal}
      Restrictions: ${user.dietaryRestrictions.join(', ')}
      Mood: ${user.mood}

      Available Menu (JSON):
      ${menuContext}

      Please recommend a specific 3-course meal (Starter, Main, Drink) strictly from the Available Menu provided.
      Explain WHY you chose these specific items based on their goal (e.g., muscle gain, weight loss).
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', 
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION_NUTRITION,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    return response.text;
  } catch (error) {
    console.error("Nutrition AI Error:", error);
    return "Our AI Nutritionist is currently consulting with the chef. Please try again.";
  }
};

// 2. Smart Pairing (Drink Recommendation)
export const getSmartPairing = async (foodName: string) => {
  try {
    const ai = getAiClient();
    const drinks = MENU_ITEMS.filter(i => i.category === 'Drink').map(d => d.name).join(', ');
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: `The guest ordered ${foodName}. From these drinks: [${drinks}], which one pairs best and why? Keep it to 1 sentence.`
    });
    return response.text;
  } catch (error) {
    return "A refreshing mineral water is always a good choice.";
  }
};

// 3. AI Gym Trainer
export const getWorkoutPlan = async (user: UserProfile, location: 'In-Room' | 'Gym') => {
  try {
    const ai = getAiClient();
    const prompt = `
      Create a 45-minute workout session.
      Guest Goal: ${user.healthGoal}
      Location: ${location}
      Current Mood: ${user.mood} (Adjust intensity based on mood)
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION_FITNESS,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Fitness AI Error:", error);
    return "Unable to generate workout plan at this moment.";
  }
};

// 4. Concierge with Search Grounding
export const getConciergeResponse = async (query: string, userLocation: string = "Zanzibar") => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User asks: ${query}. The user is currently in ${userLocation}.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION_CONCIERGE
      }
    });

    return {
      text: response.text,
      groundingChunks: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
  } catch (error) {
    console.error("Concierge Error:", error);
    return { text: "I apologize, I cannot access external information right now." };
  }
};

// 5. Text to Speech
export const generateSpeech = async (text: string) => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Fenrir' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio;
  } catch (error) {
    console.error("TTS Error:", error);
    return null;
  }
};

// 6. Generate Image (Fitness/Visual Guide)
export const generateImage = async (prompt: string) => {
  try {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: prompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Image Gen Error:", error);
    return null;
  }
};

// 7. Generate Video (Veo)
export const generateTourVideo = async (prompt: string): Promise<string | null> => {
  try {
    // Check for API key selection for Veo
    if ((window as any).aistudio) {
       const hasKey = await (window as any).aistudio.hasSelectedApiKey();
       if (!hasKey) {
         await (window as any).aistudio.openSelectKey();
         // Wait a moment or assume success as per instructions, but we need the new key in env
         // In this environment, the process.env.API_KEY is updated automatically after selection?
         // The instructions say: "Create a new GoogleGenAI instance right before making an API call"
       }
    }

    const ai = getAiClient();
    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 5000)); // Poll every 5s
      operation = await ai.operations.getVideosOperation({operation: operation});
    }

    const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (videoUri) {
      // Append key for access
      return `${videoUri}&key=${process.env.API_KEY}`;
    }
    return null;
  } catch (error) {
    console.error("Veo Error:", error);
    return null;
  }
};

