import React, { useState, useRef, useEffect } from 'react';
import { generateSpeech, getConciergeResponse, generateTourVideo } from '../services/geminiService';
import { ChatMessage } from '../types';

const WellnessChat: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: 'model', text: 'Jambo! I am your personal concierge. How may I assist you with your stay today? I can help with local tours, weather, or mental wellness facility bookings.', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [playingAudio, setPlayingAudio] = useState(false);
  const [generatingVideo, setGeneratingVideo] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const result = await getConciergeResponse(userMsg.text);
      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: result.text || "I'm having trouble connecting to the concierge desk.",
        timestamp: new Date()
      };
      setMessages(prev => [...prev, modelMsg]);

    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateVideo = async () => {
    setGeneratingVideo(true);
    // Add a placeholder message
    const placeholderId = Date.now().toString();
    setMessages(prev => [...prev, {
        id: placeholderId,
        role: 'model',
        text: "Certainly. I am generating a video preview of a bespoke tour for you. This may take a moment...",
        timestamp: new Date()
    }]);

    const prompt = "Cinematic drone shot of a luxury safari tour in Serengeti, golden hour, 4k, peaceful atmosphere";
    const videoUri = await generateTourVideo(prompt);

    if (videoUri) {
        setMessages(prev => prev.map(msg => 
            msg.id === placeholderId 
            ? { ...msg, text: "Here is a preview of the Premium Safari Experience:", videoUri } 
            : msg
        ));
    } else {
        setMessages(prev => prev.map(msg => 
            msg.id === placeholderId 
            ? { ...msg, text: "I apologize, I could not generate the video preview at this time." } 
            : msg
        ));
    }
    setGeneratingVideo(false);
  };

  const playTTS = async (text: string) => {
    if (playingAudio) return;
    setPlayingAudio(true);

    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
        }

        const ctx = audioContextRef.current;
        const binaryString = atob(base64Audio);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }

        const audioBuffer = await ctx.decodeAudioData(bytes.buffer);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start(0);

        source.onended = () => setPlayingAudio(false);
      } else {
        setPlayingAudio(false);
      }
    } catch (e) {
      console.error("Audio playback error", e);
      setPlayingAudio(false);
    }
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col bg-luxury-charcoal rounded-2xl overflow-hidden border border-luxury-gold/20 shadow-2xl">
      <div className="p-4 border-b border-white/5 bg-luxury-black/50 flex justify-between items-center">
        <h3 className="font-serif text-xl text-luxury-gold">Concierge Desk</h3>
        <div className="flex items-center gap-3">
             <button 
                onClick={handleGenerateVideo}
                disabled={generatingVideo || loading}
                className="text-[10px] uppercase border border-luxury-gold/30 px-2 py-1 rounded hover:bg-luxury-gold hover:text-black transition-colors disabled:opacity-30"
             >
                {generatingVideo ? 'Generating...' : '🎥 Preview Safari Tour'}
             </button>
            <div className="text-xs text-gray-500 flex items-center gap-2">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                Online
            </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-xl ${
              msg.role === 'user' 
                ? 'bg-luxury-gold text-black rounded-tr-none' 
                : 'bg-white/10 text-gray-200 rounded-tl-none border border-white/5'
            }`}>
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>

              {msg.videoUri && (
                  <div className="mt-3 rounded-lg overflow-hidden border border-white/20">
                      <video src={msg.videoUri} controls className="w-full" />
                  </div>
              )}

              {msg.role === 'model' && (
                <button 
                  onClick={() => playTTS(msg.text)}
                  disabled={playingAudio}
                  className="mt-2 text-xs text-luxury-gold/70 hover:text-luxury-gold flex items-center gap-1 uppercase tracking-wide disabled:opacity-50"
                >
                  {playingAudio ? '🔊 Speaking...' : '🔈 Read Aloud'}
                </button>
              )}
            </div>
          </div>
        ))}
        {loading && (
           <div className="flex justify-start">
             <div className="bg-white/5 p-4 rounded-xl rounded-tl-none border border-white/5">
                <div className="flex space-x-2">
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-100"></div>
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-200"></div>
                </div>
             </div>
           </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-luxury-black/50 border-t border-white/5">
        <div className="flex space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask about tours, weather, or requests..."
            className="flex-1 bg-luxury-charcoal border border-gray-700 text-white px-4 py-3 rounded-lg focus:outline-none focus:border-luxury-gold transition-colors"
          />
          <button 
            onClick={handleSend}
            disabled={loading}
            className="bg-luxury-gold hover:bg-yellow-500 text-black px-6 rounded-lg font-bold transition-colors disabled:opacity-50"
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
};

export default WellnessChat;

