                        <span className="text-luxury-gold font-mono">${item.price}</span>
                        <button onClick={() => removeFromCart(idx)} className="text-red-500 hover:text-red-400 px-2">&times;</button>
                      </div>
                   </div>
                 ))
               )}
            </div>

            <div className="mt-8 border-t border-white/10 pt-6">
              <div className="flex justify-between mb-2">
                <span className="text-gray-400">Subtotal</span>
                <span className="text-white">${total.toFixed(2)}</span>
              </div>
              <div className="flex justify-between mb-6">
                <span className="text-gray-400">Service Fee (10%)</span>
                <span className="text-white">${(total * 0.1).toFixed(2)}</span>
              </div>
              <div className="flex justify-between mb-8 text-xl font-bold text-luxury-gold border-t border-white/10 pt-4">
                <span>Total Due</span>
                <span>${(total * 1.1).toFixed(2)}</span>
              </div>

              <button 
                onClick={handlePayment}
                disabled={cart.length === 0}
                className="w-full bg-luxury-gold text-black py-4 rounded font-bold uppercase tracking-widest hover:bg-white transition-colors disabled:opacity-50 shadow-[0_0_15px_rgba(212,175,55,0.4)]"
              >
                Secure Checkout
              </button>
              <p className="text-center text-[10px] text-gray-500 mt-4 uppercase tracking-wider">
                Processed via SmartGuest Financial Engine
              </p>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { ROOMS } from '../constants';
import { CartItem } from '../types';

interface RoomBookingProps {
  addToCart: (item: CartItem) => void;
}

const RoomBooking: React.FC<RoomBookingProps> = ({ addToCart }) => {
  // Default to today and 3 days from now
  const today = new Date().toISOString().split('T')[0];
  const threeDaysLater = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [checkIn, setCheckIn] = useState(today);
  const [checkOut, setCheckOut] = useState(threeDaysLater);

  const calculateNights = () => {
    const start = new Date(checkIn);
    const end = new Date(checkOut);
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    return diffDays > 0 ? diffDays : 1;
  };

  const nights = calculateNights();

  const handleBook = (room: any) => {
    const totalPrice = room.price * nights;
    addToCart({
      id: `${room.id}-${Date.now()}`,
      name: room.name,
      price: totalPrice,
      type: 'Room',
      details: `${nights} Nights (${checkIn} to ${checkOut})`
    });
  };

  return (
    <div className="space-y-8">
      <header className="flex flex-col md:flex-row justify-between items-end mb-8 gap-4">
        <div>
           <h2 className="font-serif text-3xl text-luxury-gold mb-2">Accommodations</h2>
           <p className="text-gray-400">Select your sanctuary. SmartGuest ensures <span className="text-white">Complete Privacy</span>.</p>
        </div>

        {/* Date Selection Control */}
        <div className="bg-luxury-charcoal p-4 rounded-xl border border-luxury-gold/20 flex gap-4 items-center">
            <div>
                <label className="block text-[10px] uppercase tracking-widest text-gray-500 mb-1">Check In</label>
                <input 
                    type="date" 
                    value={checkIn}
                    min={today}
                    onChange={(e) => setCheckIn(e.target.value)}
                    className="bg-black/30 border border-white/10 rounded px-3 py-1 text-white text-sm focus:border-luxury-gold outline-none"
                />
            </div>
            <div className="text-luxury-gold">→</div>
            <div>
                <label className="block text-[10px] uppercase tracking-widest text-gray-500 mb-1">Check Out</label>
                <input 
                    type="date" 
                    value={checkOut}
                    min={checkIn}
                    onChange={(e) => setCheckOut(e.target.value)}
                    className="bg-black/30 border border-white/10 rounded px-3 py-1 text-white text-sm focus:border-luxury-gold outline-none"
                />
            </div>
            <div className="pl-4 border-l border-white/10 ml-2">
                <span className="block text-xl font-bold text-white text-center">{nights}</span>
                <span className="text-[10px] uppercase text-gray-500">Nights</span>
            </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {ROOMS.map((room) => {
          const totalCost = room.price * nights;
          return (
            <div key={room.id} className="bg-luxury-charcoal rounded-2xl overflow-hidden border border-gray-800 hover:border-luxury-gold/50 transition-all group flex flex-col shadow-lg">
                <div className="h-64 overflow-hidden relative">
                <img src={room.imageUrl} alt={room.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                <div className="absolute top-4 left-4 bg-luxury-gold text-black font-bold px-3 py-1 text-xs uppercase tracking-widest rounded-sm">
                    {room.type}
                </div>
                </div>
                <div className="p-6 flex-1 flex flex-col">
                <div className="flex justify-between items-start mb-4">
                    <h3 className="font-serif text-2xl text-white">{room.name}</h3>
                    <div className="text-right">
                    <span className="block text-2xl font-bold text-luxury-gold">${room.price}</span>
                    <span className="text-xs text-gray-500">per night</span>
                    </div>
                </div>
                <p className="text-gray-400 mb-6 flex-1">{room.description}</p>

                <div className="mb-6">
                    <h4 className="text-xs uppercase text-gray-500 tracking-widest mb-3">Amenities</h4>
                    <div className="flex flex-wrap gap-2">
                    {room.amenities.map(a => (
                        <span key={a} className="bg-black/40 text-gray-300 px-3 py-1 rounded-full text-xs border border-white/5">{a}</span>
                    ))}
                    </div>
                </div>

                <div className="flex items-center justify-between mt-auto pt-4 border-t border-white/5">
                    <div className="text-sm text-gray-400">
                        Total for {nights} nights: <span className="text-white font-bold">${totalCost}</span>
                    </div>
                    <button 
                        onClick={() => handleBook(room)}
                        className="px-8 py-3 bg-white/5 hover:bg-luxury-gold hover:text-black border border-luxury-gold/30 hover:border-luxury-gold text-luxury-gold font-bold uppercase tracking-wider rounded transition-all duration-300"
                    >
                        Book Stay
                    </button>
                </div>
                </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default RoomBooking;

