interface FitnessAIProps {
  addToCart: (item: CartItem) => void;
}

const FitnessAI: React.FC<FitnessAIProps> = ({ addToCart }) => {
  const [location, setLocation] = useState<'In-Room' | 'Gym'>('Gym');
