    const prompt = `A cinematic, high-quality photo of a luxury hotel ${location.toLowerCase()} setting. A fit person is performing a workout exercise appropriate for ${MOCK_USER.healthGoal}. Warm lighting, premium atmosphere.`;

    const url = await generateImage(prompt);
    if (url) {
        setVisualUrl(url);
    }
    setGeneratingVisual(false);
  };

  const handleBookSession = () => {
    if (location === 'Gym') {
        addToCart({
            id: `gym-${Date.now()}`,
            name: "Private Trainer Session",
            price: 50,
            type: 'Service',
            details: "1 Hour Personal Training"
