  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <header className="text-center mb-12">
        <h2 className="font-serif text-4xl text-luxury-gold mb-4">Body Engineering</h2>
        <p className="text-gray-400 max-w-xl mx-auto">
          Your personal AI Trainer creates bespoke workouts based on your environment. 
          Currently optimizing for: <span className="text-white">{MOCK_USER.healthGoal}</span>
        </p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
        {/* Selection Cards */}
        <button 
          onClick={() => setLocation('In-Room')}
          className={`relative p-8 rounded-2xl border-2 transition-all duration-300 text-left overflow-hidden group ${location === 'In-Room' ? 'border-luxury-gold bg-luxury-gold/10' : 'border-gray-700 hover:border-gray-500'}`}
