const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [cart, setCart] = useState<CartItem[]>(loadCart);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  // Checkout States
  const [isProcessing, setIsProcessing] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [transactionId, setTransactionId] = useState('');

  // Persistence effect
  useEffect(() => {
    localStorage.setItem('shee_cart', JSON.stringify(cart));
  }, [cart]);

  const addToCart = (item: CartItem) => {
    setCart(prev => [...prev, item]);
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  // Calculation Logic
  const subtotal = cart.reduce((acc, item) => acc + item.price, 0);
  const isRoyal = MOCK_USER.tier === UserTier.ROYAL;
  const discountRate = isRoyal ? 0.10 : 0;
  const discountAmount = subtotal * discountRate;
  const netSubtotal = subtotal - discountAmount;
  const serviceFee = netSubtotal * 0.10;
  const finalTotal = netSubtotal + serviceFee;

  const hotelShare = netSubtotal * 0.9;
  const adminShare = netSubtotal * 0.1;

  const handlePayment = () => {
    setIsProcessing(true);

    // Simulate API Network Request and Payment Gateway
    setTimeout(() => {
        setIsProcessing(false);
        setTransactionId(`TXN-${Date.now().toString().slice(-8)}`);
        setShowReceipt(true);
    }, 2500); 
  };

  const handleCloseReceipt = () => {
      setCart([]);
      setShowReceipt(false);
      setIsCheckoutOpen(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard cart={cart} />;
      case 'booking':
        return <RoomBooking addToCart={addToCart} />;
      case 'nutrition':
        return <NutritionAI addToCart={addToCart} />;
      case 'fitness':
        return <FitnessAI addToCart={addToCart} />;
      case 'concierge':
        return <WellnessChat addToCart={addToCart} />;
      default:
        return <Dashboard cart={cart} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab} userTier={MOCK_USER.tier}>
      {renderContent()}

      {/* Floating Cart Button */}
      {!isCheckoutOpen && (
        <button 
            onClick={() => setIsCheckoutOpen(true)}
            className="fixed bottom-8 right-8 bg-luxury-gold text-black p-4 rounded-full shadow-2xl hover:scale-110 transition-transform z-40 border-4 border-luxury-charcoal group"
        >
            {cart.length > 0 && (
                <span className="absolute -top-2 -right-2 bg-red-600 text-white text-xs font-bold w-6 h-6 flex items-center justify-center rounded-full animate-bounce">
                {cart.length}
                </span>
            )}
            <span className="text-2xl group-hover:rotate-12 transition-transform block">🛍️</span>
        </button>
      )}

      {/* Checkout Modal */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex justify-end animate-fade-in">
          <div className="w-full max-w-md bg-luxury-charcoal h-full border-l border-luxury-gold/30 shadow-2xl overflow-hidden flex flex-col relative">

            {/* Header */}
            <div className="p-8 pb-4 flex justify-between items-center bg-black/20">
               <h2 className="font-serif text-3xl text-luxury-gold">
                   {showReceipt ? 'Transaction Receipt' : 'Pre-Arrival Bag'}
               </h2>
               {!isProcessing && !showReceipt && (
                   <button onClick={() => setIsCheckoutOpen(false)} className="text-gray-400 hover:text-white text-2xl hover:rotate-90 transition-transform">&times;</button>
               )}
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto p-8 pt-4">
               {showReceipt ? (
                   // RECEIPT VIEW
                   <div className="space-y-6 animate-fade-in">
                       <div className="text-center py-6 border-b border-white/10">
                           <div className="w-16 h-16 bg-luxury-gold rounded-full flex items-center justify-center mx-auto mb-4 text-black text-3xl shadow-[0_0_20px_rgba(212,175,55,0.4)]">
                               ✓
                           </div>
                           <h3 className="text-white font-serif text-2xl">Payment Successful</h3>
                           <p className="text-gray-400 text-sm mt-1">Ref: {transactionId}</p>
                       </div>

                       <div className="space-y-4">
                           <p className="text-xs uppercase tracking-widest text-gray-500">Items Processed</p>
                           {cart.map((item, idx) => (
                               <div key={idx} className="flex justify-between text-sm">
                                   <span className="text-white">{item.name}</span>
                                   <span className="text-gray-400">${item.price}</span>
                               </div>
                           ))}
                       </div>

                       <div className="border-t border-white/10 pt-4 space-y-2">
                            <div className="flex justify-between text-sm">
                                <span className="text-gray-400">Subtotal</span>
                                <span className="text-white">${subtotal.toFixed(2)}</span>
