            {/* Footer / Actions */}
            <div className="p-8 border-t border-white/10 bg-black/20">
              {showReceipt ? (
                  <button 
                    onClick={handleCloseReceipt}
                    className="w-full bg-white/10 hover:bg-white/20 text-white py-4 rounded font-bold uppercase tracking-widest transition-colors border border-white/10"
