                    <button 
                        onClick={handlePayment}
                        disabled={cart.length === 0 || isProcessing}
                        className="w-full bg-luxury-gold text-black py-4 rounded font-bold uppercase tracking-widest hover:bg-white transition-all disabled:opacity-50 shadow-[0_0_15px_rgba(212,175,55,0.4)] disabled:shadow-none relative overflow-hidden"
