};

const StaffView: React.FC<DashboardProps> = ({ user, history }) => {

  // Filter items relevant to the specific staff role
  const getRelevantItems = (): { txId: string, item: CartItem, date: string }[] => {
    const items: { txId: string, item: CartItem, date: string }[] = [];
    history.forEach(tx => {
      tx.items.forEach(item => {
        let isRelevant = false;
        if (user.role === UserRole.CHEF && item.type === 'Food') isRelevant = true;
        if (user.role === UserRole.TRAINER && item.type === 'Service' && (item.name.includes('Gym') || item.name.includes('Trainer') || item.name.includes('Yoga'))) isRelevant = true;
        if (user.role === UserRole.SPA_MANAGER && item.type === 'Service' && item.name.includes('Spa')) isRelevant = true;

        if (isRelevant) {
          items.push({ txId: tx.id, item, date: tx.date });
        }
      });
    });
    return items;
  };

  const tasks = getRelevantItems();

  return (
    <div className="space-y-8 animate-fade-in">
      <header className="mb-8 flex justify-between items-center">
        <div>
            <h2 className="font-serif text-3xl text-luxury-gold">{user.role} Portal</h2>
            <p className="text-gray-400">Welcome back, {user.name}</p>
        </div>
        <div className="bg-white/5 px-4 py-2 rounded text-sm">
            Pending Tasks: <span className="font-bold text-luxury-gold">{tasks.length}</span>
        </div>
      </header>

      <div className="bg-luxury-charcoal rounded-xl border border-white/5 overflow-hidden">
        <div className="p-4 bg-black/20 border-b border-white/5">
            <h3 className="text-white font-bold">Incoming Requests / Orders</h3>
        </div>
        {tasks.length === 0 ? (
            <div className="p-12 text-center text-gray-500">
                <span className="text-4xl block mb-2">✅</span>
                No pending orders or bookings.
            </div>
        ) : (
            <div className="divide-y divide-white/5">
                {tasks.map((task, idx) => (
                    <div key={`${task.txId}-${idx}`} className="p-4 flex items-center justify-between hover:bg-white/5 transition-colors">
                        <div>
                            <p className="text-white font-bold">{task.item.name}</p>
                            <p className="text-xs text-gray-400">{new Date(task.date).toLocaleString()} • ID: {task.txId}</p>
                            {task.item.details && <p className="text-xs text-luxury-gold mt-1">{task.item.details}</p>}
                        </div>
                        <button className="bg-white/5 hover:bg-green-500/20 hover:text-green-500 border border-white/10 text-gray-300 px-4 py-2 rounded text-xs uppercase tracking-widest transition-colors">
                            Mark Done
                        </button>
                    </div>
                ))}
            </div>
        )}
      </div>
    </div>
  );
};

