  NORMAL = 'Normal',
  VIP = 'VIP',
  VVIP = 'VVIP',
  ROYAL = 'Royal'
}

export enum UserRole {
  SUPER_ADMIN = 'Super Admin',
  HOTEL_ADMIN = 'Hotel Admin',
  CHEF = 'Executive Chef',
  NUTRITIONIST = 'Nutritionist',
