  SPA_MANAGER = 'Spa Manager',
  CONCIERGE = 'Concierge Manager',
  GUEST = 'Guest'
}

export enum ServiceType {
  ROOM = 'Room',
  FOOD = 'Food',
  SPA = 'Spa',
