          <p className="text-xs text-gray-400 mt-1 uppercase tracking-widest">Ecosystem v5.0</p>
        </div>

        <div className="p-6">
          <div className="bg-gradient-to-r from-luxury-gold to-yellow-600 p-3 rounded-lg text-luxury-black mb-6">
            <p className="text-xs font-bold uppercase">Membership</p>
            <p className="font-serif text-lg">{userTier}</p>
          </div>

          {/* FR-09 Digital DND Toggle */}
          {canUseDND && (
              <div className="mb-8 p-3 bg-white/5 rounded border border-white/5 flex items-center justify-between">
                  <div>
                      <p className="text-xs font-bold text-gray-300">Privacy Mode</p>
                      <p className="text-[10px] text-gray-500">Contactless Delivery</p>
                  </div>
                  <button 
                    onClick={toggleDND}
                    className={`w-10 h-5 rounded-full p-0.5 transition-colors ${isDND ? 'bg-red-500' : 'bg-gray-600'}`}
                  >
                      <div className={`w-4 h-4 bg-white rounded-full shadow transition-transform ${isDND ? 'translate-x-5' : 'translate-x-0'}`} />
                  </button>
              </div>
          )}

          <nav className="space-y-2">
            {navItems.filter(i => i.enabled).map((item) => (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-md transition-all duration-300 ${
                  activeTab === item.id
                    ? 'bg-luxury-gold text-luxury-black font-bold'
                    : 'text-gray-400 hover:bg-white/5 hover:text-luxury-gold'
                }`}
              >
                <span className="text-xl">{item.icon}</span>
                <span>{item.label}</span>
              </button>
            ))}
          </nav>
        </div>

        <div className="mt-auto p-6 border-t border-luxury-gold/20 flex flex-col gap-4">
            <button 
                onClick={onLogout}
                className="text-xs text-red-400 hover:text-white transition-colors uppercase tracking-widest flex items-center gap-2"
            >
                <span>🚪</span> Logout
            </button>
            <p className="text-[10px] text-gray-500 text-center">&copy; 2025 SmartGuest AI</p>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 ml-64 p-8 overflow-y-auto">
        <div className="max-w-7xl mx-auto">
            {isDND && canUseDND && (
                <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded mb-6 flex justify-center items-center gap-2 text-sm animate-pulse">
                    <span>⛔</span> 
                    <strong>Privacy Mode Active:</strong> 
                    Staff will leave all deliveries at your door. No knocking.
                </div>
            )}
          {children}
        </div>
      </main>
    </div>
  );
};

