// Helper to convert raw PCM (Int16) to AudioBuffer
// Gemini TTS returns raw PCM 16-bit data, usually at 24kHz
const pcmToAudioBuffer = (
  data: Uint8Array, 
  ctx: AudioContext, 
  sampleRate: number = 24000, 
  numChannels: number = 1
): AudioBuffer => {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      // Convert Int16 (-32768 to 32767) to Float32 (-1.0 to 1.0)
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
};

const WellnessChat: React.FC<WellnessChatProps> = ({ addToCart }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: 'model', text: 'Jambo! I am your personal concierge. I can help you plan your stay, find local gems, or book activities. Try asking: "What are good sunset spots nearby?"', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  // Changed from boolean to string | null to track WHICH message is playing
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [generatingVideo, setGeneratingVideo] = useState(false);

  // Itinerary State
  const [itinerary, setItinerary] = useState<ItineraryItem[]>([]);

  const audioContextRef = useRef<AudioContext | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Parse JSON suggestions from text if available
  const extractSuggestions = (text: string): { cleanText: string, suggestions: ItineraryItem[] } => {
    let cleanText = text;
    let suggestions: ItineraryItem[] = [];

    const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch && jsonMatch[1]) {
        try {
            const parsed = JSON.parse(jsonMatch[1]);
            if (Array.isArray(parsed)) {
                suggestions = parsed.map((item: any, idx) => ({
                    id: `sugg-${Date.now()}-${idx}`,
                    title: item.title,
                    time: item.time,
                    location: item.location,
                    description: item.description,
                    mapQuery: item.mapQuery,
                    isBooked: false
                }));
            }
            // Remove the JSON block from display text to keep UI clean
            cleanText = text.replace(jsonMatch[0], '').trim();
        } catch (e) {
            console.error("Failed to parse activity JSON", e);
        }
    }
    return { cleanText, suggestions };
  };

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const result = await getConciergeResponse(userMsg.text);

      const { cleanText, suggestions } = extractSuggestions(result.text || "");

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: cleanText || "I'm checking the schedule...",
        timestamp: new Date(),
        suggestedActivities: suggestions.length > 0 ? suggestions : undefined
      };
      setMessages(prev => [...prev, modelMsg]);

    } catch (e) {
      console.error(e);
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: "I'm having trouble connecting to the network.", timestamp: new Date() }]);
    } finally {
      setLoading(false);
    }
  };

  const addToItinerary = (item: ItineraryItem) => {
      if (itinerary.some(i => i.id === item.id)) return;
      setItinerary(prev => [...prev, { ...item, isBooked: true }].sort((a, b) => a.time.localeCompare(b.time)));

      // Optionally add a notification message
      setMessages(prev => [...prev, {
          id: Date.now().toString(),
          role: 'model',
          text: `Confirmed! I've added "${item.title}" at ${item.time} to your schedule.`,
          timestamp: new Date()
      }]);
  };

  const removeFromItinerary = (id: string) => {
      setItinerary(prev => prev.filter(i => i.id !== id));
  };

  const handleGenerateVideo = async () => {
    setGeneratingVideo(true);
    const placeholderId = Date.now().toString();
    setMessages(prev => [...prev, {
        id: placeholderId,
        role: 'model',
        text: "Certainly. I am generating a video preview of a bespoke tour for you. This may take a moment...",
        timestamp: new Date()
    }]);

    const prompt = "Cinematic drone shot of a luxury safari tour in Serengeti, golden hour, 4k, peaceful atmosphere";
    const videoUri = await generateTourVideo(prompt);

    if (videoUri) {
        setMessages(prev => prev.map(msg => 
            msg.id === placeholderId 
            ? { ...msg, text: "Here is a preview of the Premium Safari Experience:", videoUri } 
            : msg
        ));
    } else {
        setMessages(prev => prev.map(msg => 
            msg.id === placeholderId 
            ? { ...msg, text: "I apologize, I could not generate the video preview at this time." } 
            : msg
        ));
    }
    setGeneratingVideo(false);
  };

  const playTTS = async (id: string, text: string) => {
    // If audio is already playing, do not start another one
    if (playingMessageId) return;

    setPlayingMessageId(id);

    try {
      const base64Audio = await generateSpeech(text);
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
        }

        const ctx = audioContextRef.current;
        const binaryString = atob(base64Audio);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }

        // Use manual PCM decoding instead of native decodeAudioData
        const audioBuffer = pcmToAudioBuffer(bytes, ctx, 24000); 

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start(0);

        source.onended = () => setPlayingMessageId(null);
      } else {
        setPlayingMessageId(null);
      }
    } catch (e) {
      console.error("Audio playback error", e);
      setPlayingMessageId(null);
    }
  };

  const handleQuickAction = (action: string, price: number) => {
    addToCart({
        id: `service-${Date.now()}`,
        name: action,
        price: price,
        type: 'Service',
        details: 'Requested via Concierge'
    });
    setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: `Confirmed. I have added "${action}" to your billing.`,
        timestamp: new Date()
    }]);
  };

  return (
    <div className="h-[calc(100vh-8rem)] flex flex-col md:flex-row gap-6">
      {/* Chat Area */}
      <div className="flex-1 flex flex-col bg-luxury-charcoal rounded-2xl overflow-hidden border border-luxury-gold/20 shadow-2xl">
          <div className="p-4 border-b border-white/5 bg-luxury-black/50 flex justify-between items-center">
            <h3 className="font-serif text-xl text-luxury-gold">Concierge & Planner</h3>
            <div className="flex items-center gap-3">
                <button 
                    onClick={handleGenerateVideo}
                    disabled={generatingVideo || loading}
                    className="hidden md:block text-[10px] uppercase border border-luxury-gold/30 px-2 py-1 rounded hover:bg-luxury-gold hover:text-black transition-colors disabled:opacity-30"
                >
                    {generatingVideo ? 'Generating...' : '🎥 Preview Safari'}
                </button>
                <div className="text-xs text-gray-500 flex items-center gap-2">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    Online
                </div>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-xl ${
                  msg.role === 'user' 
                    ? 'bg-luxury-gold text-black rounded-tr-none' 
                    : 'bg-white/10 text-gray-200 rounded-tl-none border border-white/5'
                }`}>
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>

                  {msg.videoUri && (
                      <div className="mt-3 rounded-lg overflow-hidden border border-white/20">
                          <video src={msg.videoUri} controls className="w-full" />
                      </div>
                  )}

                  {msg.role === 'model' && (
                    <button 
                      onClick={() => playTTS(msg.id, msg.text)}
                      disabled={playingMessageId !== null && playingMessageId !== msg.id}
                      className={`mt-2 text-xs flex items-center gap-1 uppercase tracking-wide disabled:opacity-50 transition-colors ${
                          playingMessageId === msg.id 
                          ? 'text-luxury-gold font-bold animate-pulse' 
                          : 'text-luxury-gold/70 hover:text-luxury-gold'
                      }`}
                    >
                      {playingMessageId === msg.id ? '🔊 Speaking...' : '🔈 Read Aloud'}
                    </button>
                  )}
                </div>

                {/* Activity Suggestions Cards */}
                {msg.suggestedActivities && msg.suggestedActivities.length > 0 && (
                    <div className="mt-3 w-full max-w-[90%] grid grid-cols-1 gap-3 animate-fade-in">
                        <p className="text-xs text-gray-500 uppercase tracking-widest ml-1">Suggested for you</p>
                        {msg.suggestedActivities.map((activity) => (
                            <div key={activity.id} className="bg-black/40 border border-luxury-gold/30 p-4 rounded-lg flex justify-between items-center gap-4 hover:border-luxury-gold transition-colors">
                                <div className="flex-1">
                                    <h4 className="font-bold text-white text-sm">{activity.title}</h4>
                                    <div className="flex items-center gap-3 text-xs text-gray-400 mt-1">
                                        <span className="text-luxury-gold">⏰ {activity.time}</span>
                                        <span>📍 {activity.location}</span>
                                    </div>
                                    <p className="text-xs text-gray-500 mt-2 line-clamp-1">{activity.description}</p>
                                    <a 
                                      href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(activity.mapQuery)}`} 
                                      target="_blank" 
                                      rel="noreferrer"
                                      className="text-[10px] text-blue-400 hover:text-blue-300 mt-2 inline-flex items-center gap-1"
                                    >
                                        🗺️ View on Google Maps
                                    </a>
                                </div>
                                <button 
                                    onClick={() => addToItinerary(activity)}
                                    className="bg-luxury-gold/20 hover:bg-luxury-gold text-luxury-gold hover:text-black border border-luxury-gold/50 rounded-full p-2 transition-colors"
                                    title="Add to Schedule"
                                >
                                    {itinerary.some(i => i.title === activity.title) ? '✓' : '+'}
                                </button>
                            </div>
                        ))}
                    </div>
                )}
              </div>
            ))}
            {loading && (
               <div className="flex justify-start">
                 <div className="bg-white/5 p-4 rounded-xl rounded-tl-none border border-white/5">
                    <div className="flex space-x-2">
                      <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-100"></div>
                      <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce delay-200"></div>
                    </div>
                 </div>
               </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          <div className="p-4 bg-luxury-black/50 border-t border-white/5 space-y-3">
            {/* Quick Actions */}
            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-thin">
                <button onClick={() => handleQuickAction('Deep Tissue Spa Massage', 120)} className="whitespace-nowrap bg-white/5 hover:bg-luxury-gold/20 text-xs px-3 py-1 rounded-full border border-white/10 text-gray-300 transition-colors">💆 Book Spa ($120)</button>
                <button onClick={() => handleQuickAction('Room Cleaning', 0)} className="whitespace-nowrap bg-white/5 hover:bg-luxury-gold/20 text-xs px-3 py-1 rounded-full border border-white/10 text-gray-300 transition-colors">🧹 Tidy Room</button>
                <button onClick={() => handleQuickAction('Late Checkout', 50)} className="whitespace-nowrap bg-white/5 hover:bg-luxury-gold/20 text-xs px-3 py-1 rounded-full border border-white/10 text-gray-300 transition-colors">⏰ Late Checkout ($50)</button>
            </div>

            <div className="flex space-x-2">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask about tours, weather, or requests..."
                className="flex-1 bg-luxury-charcoal border border-gray-700 text-white px-4 py-3 rounded-lg focus:outline-none focus:border-luxury-gold transition-colors"
              />
              <button 
                onClick={handleSend}
                disabled={loading}
                className="bg-luxury-gold hover:bg-yellow-500 text-black px-6 rounded-lg font-bold transition-colors disabled:opacity-50"
              >
                Send
              </button>
            </div>
          </div>
      </div>

      {/* Itinerary Panel (Schedule) */}
      <div className="w-full md:w-80 bg-luxury-charcoal rounded-2xl border border-luxury-gold/20 shadow-xl flex flex-col h-[400px] md:h-auto overflow-hidden">
          <div className="p-4 bg-black/40 border-b border-white/10">
              <h3 className="text-luxury-gold font-serif text-lg">My Itinerary</h3>
              <p className="text-xs text-gray-500">Scheduled Activities</p>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {itinerary.length === 0 ? (
                  <div className="text-center mt-10 text-gray-500 opacity-60">
                      <div className="text-4xl mb-2">📅</div>
                      <p className="text-sm">No activities scheduled yet.</p>
                      <p className="text-xs mt-2">Ask the concierge for suggestions!</p>
                  </div>
              ) : (
                  <div className="relative border-l border-white/10 ml-2 space-y-6">
                      {itinerary.map((item, idx) => (
                          <div key={idx} className="ml-6 relative">
                              <span className="absolute -left-[29px] top-0 w-3 h-3 bg-luxury-gold rounded-full border-2 border-black"></span>
                              <div className="bg-white/5 border border-white/5 p-3 rounded-lg hover:border-luxury-gold/50 transition-colors group">
                                  <div className="flex justify-between items-start">
                                      <span className="text-xs font-mono text-luxury-gold bg-luxury-gold/10 px-1 rounded">{item.time}</span>
                                      <button onClick={() => removeFromItinerary(item.id)} className="text-gray-600 hover:text-red-400 text-xs">&times;</button>
                                  </div>
                                  <h4 className="text-white font-bold text-sm mt-1">{item.title}</h4>
                                  <p className="text-gray-400 text-xs mt-1">{item.location}</p>
                                  <a 
                                      href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.mapQuery)}`} 
                                      target="_blank" 
                                      rel="noreferrer"
                                      className="text-[10px] text-blue-400 hover:text-blue-300 mt-2 block"
                                  >
                                      View Map →
                                  </a>
                              </div>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      </div>
    </div>
  );
};

