const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);

  // App Logic State
  const [activeTab, setActiveTab] = useState('dashboard');
  const [cart, setCart] = useState<CartItem[]>(loadCart);
  const [history, setHistory] = useState<Transaction[]>(loadHistory);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [commissionRate, setCommissionRate] = useState<number>(10); // Default 10%
  const [symptomLogs, setSymptomLogs] = useState<SymptomLogEntry[]>(loadSymptomLogs);

  // FR-09: Digital DND
  const [isDND, setIsDND] = useState(false);

  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  // Feature Flags (Managed by Super Admin)
  const [features, setFeatures] = useState<AppFeatures>({
    nutrition: true,
    fitness: true,
    spa: true,
    concierge: true
  });

  // Checkout States
  const [isProcessing, setIsProcessing] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const [transactionId, setTransactionId] = useState('');

  // Persistence effects
  useEffect(() => {
    localStorage.setItem('shee_cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('shee_history', JSON.stringify(history));
  }, [history]);

  // Persist commission rate for Super Admin consistency
  useEffect(() => {
    const savedRate = localStorage.getItem('shee_commission');
    if (savedRate) setCommissionRate(Number(savedRate));
  }, []);

  useEffect(() => {
    localStorage.setItem('shee_commission', commissionRate.toString());
  }, [commissionRate]);

  useEffect(() => {
      localStorage.setItem('shee_symptom_logs', JSON.stringify(symptomLogs));
  }, [symptomLogs]);


  // Handlers
  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    setActiveTab('dashboard'); // Reset tab on login
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCart([]); // Optional: clear cart on logout
    setIsCheckoutOpen(false);
    setIsDND(false);
  };

  const toggleFeature = (key: keyof AppFeatures) => {
    setFeatures(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const addToCart = (item: CartItem) => {
    // Inject DND status if active
    const finalItem = {
        ...item,
        status: 'Pending',
        deliveryMode: isDND ? 'Contactless (DND)' : 'Standard',
        details: isDND && !item.details?.includes('Contactless') ? `${item.details || ''} [Contactless]` : item.details
    };
    setCart(prev => [...prev, finalItem as CartItem]);
  };

  const handleLogSymptom = (entry: SymptomLogEntry) => {
      setSymptomLogs(prev => [entry, ...prev]);
  };

  const removeFromCart = (index: number) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const markTaskComplete = (txId: string, itemId: string) => {
    setHistory(prevHistory => {
        return prevHistory.map(tx => {
            if (tx.id === txId) {
                return {
                    ...tx,
                    items: tx.items.map(item => 
                        item.id === itemId ? { ...item, status: 'Completed' } : item
                    )
                };
            }
            return tx;
        });
    });
  };

  // Calculation Logic (Only for Checkout)
  const subtotal = cart.reduce((acc, item) => acc + item.price, 0);
  const isRoyal = currentUser?.tier === UserTier.ROYAL;
  const discountRate = isRoyal ? 0.10 : 0;
  const discountAmount = subtotal * discountRate;
  const netSubtotal = subtotal - discountAmount;
  const serviceFee = netSubtotal * 0.10;
  const finalTotal = netSubtotal + serviceFee;

  const hotelShare = netSubtotal * ((100 - commissionRate) / 100);
  const adminShare = netSubtotal * (commissionRate / 100);

  const handlePayment = () => {
    setIsProcessing(true);
    setTimeout(() => {
        setIsProcessing(false);
        const txnId = `TXN-${Date.now().toString().slice(-8)}`;
        setTransactionId(txnId);
        const newTxn: Transaction = {
            id: txnId,
            date: new Date().toISOString(),
            items: cart.map(item => ({...item, status: 'Pending'})), // Ensure status is pending
            total: finalTotal
        };
        setHistory(prev => [newTxn, ...prev]);
        setShowReceipt(true);
    }, 2500); 
  };

  const handleCloseReceipt = () => {
      setCart([]);
      setShowReceipt(false);
      setIsCheckoutOpen(false);
  };

  // RENDER LOGIC

  // 1. Not Logged In
  if (!currentUser) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  // 2. Admin / Staff Views (Unified Dashboard Component)
  if (currentUser.role !== UserRole.GUEST) {
    return (
        <AdminDashboards 
            user={currentUser} 
            history={history} 
            features={features}
            toggleFeature={toggleFeature}
            onLogout={handleLogout}
            commissionRate={commissionRate}
            setCommissionRate={setCommissionRate}
            inventory={inventory}
            setInventory={setInventory}
            markTaskComplete={markTaskComplete}
        />
    );
  }

  // 3. Guest View (Existing Layout & logic)
  const renderGuestContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard cart={cart} history={history} user={currentUser} commissionRate={commissionRate} symptomLogs={symptomLogs} />;
      case 'booking':
        return <RoomBooking addToCart={addToCart} />;
      case 'nutrition':
        return <NutritionAI addToCart={addToCart} />;
      case 'fitness':
        return <FitnessAI addToCart={addToCart} isDND={isDND} />;
      case 'spa':
        return <SpaWellness addToCart={addToCart} isDND={isDND} onLogSymptom={handleLogSymptom} />;
      case 'concierge':
        return <WellnessChat addToCart={addToCart} />;
      default:
        return <Dashboard cart={cart} history={history} user={currentUser} commissionRate={commissionRate} symptomLogs={symptomLogs} />;
    }
  };

  return (
    <Layout 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userTier={currentUser.tier} 
        enabledFeatures={features}
        onLogout={handleLogout}
        isDND={isDND}
        toggleDND={() => setIsDND(!isDND)}
    >
      {renderGuestContent()}

      {/* Floating Cart Button (Guest Only) */}
      {!isCheckoutOpen && (
        <button 
            onClick={() => setIsCheckoutOpen(true)}
            className="fixed bottom-8 right-8 bg-luxury-gold text-black p-4 rounded-full shadow-2xl hover:scale-110 transition-transform z-40 border-4 border-luxury-charcoal group"
        >
            {cart.length > 0 && (
                <span className="absolute -top-2 -right-2 bg-red-600 text-white text-xs font-bold w-6 h-6 flex items-center justify-center rounded-full animate-bounce">
                {cart.length}
                </span>
            )}
            <span className="text-2xl group-hover:rotate-12 transition-transform block">🛍️</span>
        </button>
      )}

      {/* Checkout Modal (Guest Only) */}
      {isCheckoutOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex justify-end animate-fade-in p-4">
          <div className="w-full max-w-md bg-luxury-charcoal h-full border-l border-luxury-gold/30 shadow-2xl overflow-hidden flex flex-col relative rounded-xl md:rounded-none ml-auto">
            <div className="p-8 pb-4 flex justify-between items-center bg-black/20">
               <h2 className="font-serif text-2xl md:text-3xl text-luxury-gold">
                   {showReceipt ? 'Transaction Receipt' : 'Pre-Arrival Bag'}
               </h2>
               {!isProcessing && !showReceipt && (
                   <button onClick={() => setIsCheckoutOpen(false)} className="text-gray-400 hover:text-white text-2xl hover:rotate-90 transition-transform">&times;</button>
               )}
            </div>

            <div className="flex-1 overflow-y-auto p-8 pt-4">
               {showReceipt ? (
                   <div className="space-y-6 animate-fade-in">
                       <div className="text-center py-6 border-b border-white/10">
                           <div className="w-16 h-16 bg-luxury-gold rounded-full flex items-center justify-center mx-auto mb-4 text-black text-3xl shadow-[0_0_20px_rgba(212,175,55,0.4)]">✓</div>
                           <h3 className="text-white font-serif text-2xl">Payment Successful</h3>
                           <p className="text-gray-400 text-sm mt-1">Ref: {transactionId}</p>
                       </div>
                       <div className="space-y-4">
                           <p className="text-xs uppercase tracking-widest text-gray-500">Items Processed</p>
                           {cart.map((item, idx) => (
                               <div key={idx} className="flex justify-between text-sm">
                                   <span className="text-white">{item.name}</span>
                                   <span className="text-gray-400">${item.price}</span>
                               </div>
                           ))}
                       </div>
                       <div className="border-t border-white/10 pt-4 space-y-2">
                            <div className="flex justify-between text-sm"><span className="text-gray-400">Subtotal</span><span className="text-white">${subtotal.toFixed(2)}</span></div>
                            {isRoyal && <div className="flex justify-between text-sm"><span className="text-luxury-gold">Royal Discount</span><span className="text-luxury-gold">-${discountAmount.toFixed(2)}</span></div>}
                            <div className="flex justify-between text-sm"><span className="text-gray-400">Service Fee</span><span className="text-white">${serviceFee.toFixed(2)}</span></div>
                            <div className="flex justify-between text-xl font-bold text-luxury-gold pt-2 border-t border-dashed border-gray-700 mt-2"><span>Total Paid</span><span>${finalTotal.toFixed(2)}</span></div>
                       </div>
                       <div className="bg-black/30 p-4 rounded text-xs text-gray-500 mt-8 border border-white/5">
                           <p className="uppercase tracking-widest mb-2 font-bold opacity-50">SmartGuest Financial Engine (Split)</p>
                           <div className="flex justify-between"><span>Hotel Revenue ({100 - commissionRate}%):</span><span>${hotelShare.toFixed(2)}</span></div>
                           <div className="flex justify-between"><span>Platform Commission ({commissionRate}%):</span><span>${adminShare.toFixed(2)}</span></div>
                       </div>
                   </div>
               ) : (
                   <div className="space-y-4">
                        {cart.length === 0 ? (
                            <div className="text-center mt-20 opacity-50"><div className="text-6xl mb-4">🕸️</div><p className="text-gray-400">Your itinerary is empty.</p></div>
                        ) : (
                            cart.map((item, idx) => (
                            <div key={idx} className="flex justify-between items-center bg-white/5 p-4 rounded border border-white/5 hover:border-luxury-gold/30 transition-colors">
                                <div>
                                    <h4 className="font-bold text-white">{item.name}</h4>
                                    <div className="flex flex-wrap items-center gap-2">
                                        <span className="text-[10px] uppercase bg-luxury-gold/20 text-luxury-gold px-1 rounded">{item.type}</span>
                                        {item.deliveryMode === 'Contactless (DND)' && <span className="text-[10px] uppercase bg-red-500/20 text-red-400 px-1 rounded">DND</span>}
                                        {item.locationTier && <span className="text-[10px] uppercase bg-blue-500/20 text-blue-400 px-1 rounded">{item.locationTier}</span>}
                                    </div>
                                    {/* Show little icon if it has AI reasoning */}
                                    {item.aiReasoning && (
                                        <div className="text-[10px] text-gray-400 mt-1 flex items-center gap-1">
                                            <span>🧠 AI Recommended</span>
                                        </div>
                                    )}
                                </div>
                                <div className="flex items-center space-x-4"><span className="text-luxury-gold font-mono">${item.price}</span><button onClick={() => removeFromCart(idx)} disabled={isProcessing} className="text-red-500 hover:text-red-400 px-2 disabled:opacity-30">&times;</button></div>
                            </div>
                            ))
                        )}
                   </div>
               )}
            </div>

            <div className="p-8 border-t border-white/10 bg-black/20">
              {showReceipt ? (
                  <button onClick={handleCloseReceipt} className="w-full bg-white/10 hover:bg-white/20 text-white py-4 rounded font-bold uppercase tracking-widest transition-colors border border-white/10">Close & Start New Itinerary</button>
              ) : (
                  <>
                    <div className="flex justify-between mb-2"><span className="text-gray-400">Subtotal</span><span className="text-white">${subtotal.toFixed(2)}</span></div>
                    {isRoyal && <div className="flex justify-between mb-2"><span className="text-luxury-gold">Royal Discount (10%)</span><span className="text-luxury-gold">-${discountAmount.toFixed(2)}</span></div>}
                    <div className="flex justify-between mb-6"><span className="text-gray-400">Service Fee (10%)</span><span className="text-white">${serviceFee.toFixed(2)}</span></div>
                    <div className="flex justify-between mb-8 text-xl font-bold text-luxury-gold border-t border-white/10 pt-4"><span>Total Due</span><span>${finalTotal.toFixed(2)}</span></div>
                    <button onClick={handlePayment} disabled={cart.length === 0 || isProcessing} className="w-full bg-luxury-gold text-black py-4 rounded font-bold uppercase tracking-widest hover:bg-white transition-all disabled:opacity-50 shadow-[0_0_15px_rgba(212,175,55,0.4)] disabled:shadow-none relative overflow-hidden">
                        {isProcessing ? <div className="flex items-center justify-center gap-3"><div className="w-4 h-4 border-2 border-black border-t-transparent rounded-full animate-spin"></div><span>Processing...</span></div> : 'Secure Checkout'}
                    </button>
                    <p className="text-center text-[10px] text-gray-500 mt-4 uppercase tracking-wider">Processed via SmartGuest Financial Engine</p>
                  </>
              )}
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { SPA_TREATMENTS, TECH_AMENITIES, MOCK_USER } from '../constants';
import { getSpaRecommendation } from '../services/geminiService';
import { CartItem, LocationTier, SpaTreatment, SymptomLogEntry } from '../types';

interface SpaWellnessProps {
  addToCart: (item: CartItem) => void;
  isDND: boolean;
  onLogSymptom: (entry: SymptomLogEntry) => void;
}

const SpaWellness: React.FC<SpaWellnessProps> = ({ addToCart, isDND, onLogSymptom }) => {
  const [activeSection, setActiveSection] = useState<'treatments' | 'mind'>('treatments');
  const [selectedSymptoms, setSelectedSymptoms] = useState<string[]>([]);
  const [recommendation, setRecommendation] = useState<{ treatment: SpaTreatment, reasoning: string } | null>(null);
  const [loading, setLoading] = useState(false);
  const [locationTier, setLocationTier] = useState<LocationTier>(LocationTier.STANDARD);
  const [isReasoningExpanded, setIsReasoningExpanded] = useState(false);

  // Persistence for Location Tier
  useEffect(() => {
    const savedTier = localStorage.getItem('shee_spa_prefs');
    if (savedTier) {
        // Simple string check to ensure it's a valid enum value
        if (Object.values(LocationTier).includes(savedTier as LocationTier)) {
            setLocationTier(savedTier as LocationTier);
        }
    }
  }, []);

  const handleTierChange = (tier: LocationTier) => {
      setLocationTier(tier);
      localStorage.setItem('shee_spa_prefs', tier);
  };

  const symptoms = ["Jetlag", "Muscle Soreness", "Stress/Anxiety", "Sunburn", "Insomnia", "Fatigue"];

  const toggleSymptom = (symptom: string) => {
    setSelectedSymptoms(prev => 
        prev.includes(symptom) ? prev.filter(s => s !== symptom) : [...prev, symptom]
    );
  };

  const handleConsultAI = async () => {
    if (selectedSymptoms.length === 0) return;
    setLoading(true);
    setRecommendation(null);
    setIsReasoningExpanded(false);

    const result = await getSpaRecommendation(selectedSymptoms);
    if (result && result.treatmentId) {
        const treatment = SPA_TREATMENTS.find(t => t.id === result.treatmentId);
        if (treatment) {
            setRecommendation({ treatment, reasoning: result.reasoning });

            // Log to history
            onLogSymptom({
                id: Date.now().toString(),
                date: new Date().toISOString(),
                symptoms: selectedSymptoms,
                recommendedTreatmentName: treatment.name,
                reasoning: result.reasoning
            });
        }
    }
    setLoading(false);
  };

  const getPrice = (basePrice: number) => {
      if (locationTier === LocationTier.IN_ROOM) return basePrice * 1.2; // 20% Surcharge
      if (locationTier === LocationTier.PRIVATE) return basePrice + 100; // Flat fee
      return basePrice;
  };

  const bookTreatment = (treatment: SpaTreatment) => {
      // Check if this treatment matches the current AI recommendation to attach context
      const isRecommended = recommendation?.treatment.id === treatment.id;
      const aiContext = isRecommended ? {
          symptoms: selectedSymptoms,
          aiReasoning: recommendation.reasoning
      } : {};

      addToCart({
          id: `spa-${Date.now()}`,
          name: treatment.name,
          price: getPrice(treatment.price),
          type: 'Service',
          locationTier: locationTier,
          details: `${locationTier} • ${treatment.durationMin} min${isDND ? ' • Contactless' : ''}`,
          deliveryMode: isDND ? 'Contactless (DND)' : 'Standard',
          ...aiContext
      });
  };

  const rentTech = (item: typeof TECH_AMENITIES[0]) => {
      addToCart({
          id: `tech-${Date.now()}`,
          name: `Rental: ${item.name}`,
          price: item.pricePerDay,
          type: 'Rental',
          details: '24 Hour Rental • Delivered to Room',
          deliveryMode: isDND ? 'Contactless (DND)' : 'Standard'
      });
  };

  return (
    <div className="space-y-8 animate-fade-in">
        <header className="mb-8">
            <h2 className="font-serif text-3xl text-luxury-gold mb-2">Spa & Mental Wellness</h2>
            <p className="text-gray-400">Restore your balance. Treatments curated by AI for your specific state.</p>
        </header>

        {/* Navigation Tabs */}
        <div className="flex gap-4 border-b border-white/10 pb-4">
            <button onClick={() => setActiveSection('treatments')} className={`text-lg font-serif transition-colors ${activeSection === 'treatments' ? 'text-luxury-gold border-b-2 border-luxury-gold' : 'text-gray-500 hover:text-white'}`}>Body Therapies</button>
            <button onClick={() => setActiveSection('mind')} className={`text-lg font-serif transition-colors ${activeSection === 'mind' ? 'text-luxury-gold border-b-2 border-luxury-gold' : 'text-gray-500 hover:text-white'}`}>Mind & Tech Rentals</button>
        </div>

        {activeSection === 'treatments' && (
            <div className="space-y-8">
                {/* Location Tier Selector - Moved to top for context */}
                <div className="bg-black/20 p-6 rounded-xl border border-white/5">
                    <div className="mb-4 flex justify-between items-center">
                        <div>
                            <h4 className="text-sm font-bold text-gray-300 uppercase tracking-widest">Select Experience Level</h4>
                            <p className="text-xs text-gray-500">Prices update automatically based on your selection.</p>
                        </div>
                        <div className="text-[10px] text-green-500 bg-green-500/10 px-2 py-1 rounded border border-green-500/20">
                            Preference Saved ✓
                        </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        {[
                            { tier: LocationTier.STANDARD, label: 'Spa Facility', priceInfo: 'Standard Rates' },
                            { tier: LocationTier.IN_ROOM, label: 'In-Room Service', priceInfo: '+20% Surcharge' },
                            { tier: LocationTier.PRIVATE, label: 'Private Suite', priceInfo: '+$100 Flat Fee' }
                        ].map(({ tier, label, priceInfo }) => (
                            <button
                                key={tier}
                                onClick={() => handleTierChange(tier)}
                                className={`p-4 rounded-lg border text-left transition-all relative overflow-hidden group ${
                                    locationTier === tier 
                                    ? 'bg-luxury-gold/10 border-luxury-gold' 
                                    : 'bg-luxury-charcoal border-white/10 hover:border-luxury-gold/50'
                                }`}
                            >
                                <div className={`absolute top-0 right-0 p-2 text-4xl opacity-10 ${locationTier === tier ? 'text-luxury-gold' : 'text-gray-500'}`}>
                                    {tier === LocationTier.STANDARD ? '🌿' : tier === LocationTier.IN_ROOM ? '🛏️' : '👑'}
                                </div>
                                <p className={`font-bold ${locationTier === tier ? 'text-luxury-gold' : 'text-white'}`}>{label}</p>
                                <p className="text-xs text-gray-400 mt-1">{priceInfo}</p>
                                {locationTier === tier && <div className="absolute inset-0 border-2 border-luxury-gold rounded-lg pointer-events-none" />}
                            </button>
                        ))}
                    </div>
                </div>

                {/* AI Symptom Checker */}
                <div className="bg-luxury-charcoal p-8 rounded-xl border border-luxury-gold/20 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-5 text-9xl">🌿</div>
                    <h3 className="text-xl font-bold text-white mb-4">How are you feeling today?</h3>
                    <div className="flex flex-wrap gap-3 mb-6">
                        {symptoms.map(sym => (
                            <button 
                                key={sym}
                                onClick={() => toggleSymptom(sym)}
                                className={`px-4 py-2 rounded-full border transition-all flex items-center gap-2 ${
                                    selectedSymptoms.includes(sym)
                                    ? 'bg-luxury-gold text-black border-luxury-gold font-bold shadow-[0_0_10px_rgba(212,175,55,0.4)] transform scale-105'
                                    : 'bg-white/5 text-gray-400 border-white/10 hover:border-luxury-gold/50'
                                }`}
                            >
                                {selectedSymptoms.includes(sym) && <span>✓</span>}
                                {sym}
                            </button>
                        ))}
                    </div>

                    <button 
                        onClick={handleConsultAI}
                        disabled={loading || selectedSymptoms.length === 0}
                        className="bg-white/10 hover:bg-luxury-gold hover:text-black text-white px-6 py-3 rounded font-bold uppercase tracking-widest transition-colors disabled:opacity-30"
                    >
                        {loading ? 'Consulting Therapist AI...' : 'Find Perfect Treatment'}
                    </button>

                    {recommendation && (
                        <div className="mt-6 bg-black/40 p-6 rounded-lg border-l-4 border-luxury-gold animate-fade-in flex flex-col md:flex-row justify-between items-start md:items-start gap-6">
                            <div className="flex-1 w-full">
                                <div className="flex items-center gap-2 mb-2">
                                     <span className="bg-luxury-gold/20 text-luxury-gold text-[10px] px-2 py-1 rounded uppercase font-bold tracking-widest">AI Recommended</span>
                                </div>
                                <h4 className="text-white font-serif text-2xl mb-2">{recommendation.treatment.name}</h4>

                                <div className="mb-4">
                                    <button 
                                        onClick={() => setIsReasoningExpanded(!isReasoningExpanded)}
                                        className="text-xs text-luxury-gold flex items-center gap-1 hover:underline mb-2"
                                    >
                                        {isReasoningExpanded ? 'Hide AI Reasoning' : 'Show AI Reasoning'} 
                                        <span>{isReasoningExpanded ? '▲' : '▼'}</span>
                                    </button>

                                    {isReasoningExpanded && (
                                        <div className="bg-white/5 p-3 rounded text-sm text-gray-300 italic border border-white/5 animate-fade-in">
                                            "{recommendation.reasoning}"
                                        </div>
                                    )}
                                </div>

                                <div className="flex items-center gap-4 text-sm text-gray-400">
                                    <span className="flex items-center gap-1">⏱ {recommendation.treatment.durationMin} mins</span>
                                    <span className="flex items-center gap-1">🏷 {recommendation.treatment.tags.join(', ')}</span>
                                </div>
                            </div>
                            <div className="flex flex-col items-end gap-3 min-w-[140px] w-full md:w-auto">
                                <div className="text-right">
                                    <p className="text-xs text-gray-500 uppercase tracking-wider mb-1">Total Price</p>
                                    <p className="text-2xl font-serif text-luxury-gold">${getPrice(recommendation.treatment.price).toFixed(0)}</p>
                                    {locationTier !== LocationTier.STANDARD && <p className="text-[10px] text-gray-500">Includes surcharge</p>}
                                </div>
                                <button 
                                    onClick={() => bookTreatment(recommendation.treatment)} 
                                    className="w-full bg-luxury-gold text-black px-4 py-3 rounded font-bold text-sm hover:bg-white transition-colors shadow-lg uppercase tracking-wider"
                                >
                                    Book Now
                                </button>
                            </div>
                        </div>
                    )}
                </div>

                {/* Treatment List */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {SPA_TREATMENTS.map(t => (
                        <div key={t.id} className="bg-luxury-charcoal p-6 rounded-xl border border-white/5 hover:border-luxury-gold/30 transition-all group flex flex-col">
                            <div className="flex justify-between items-start mb-2">
                                <h4 className="text-xl font-serif text-white group-hover:text-luxury-gold transition-colors">{t.name}</h4>
                                <span className="font-mono text-luxury-gold text-lg">${getPrice(t.price).toFixed(0)}</span>
                            </div>
                            <p className="text-sm text-gray-400 mb-4 h-12">{t.description}</p>
                            <div className="mt-auto flex justify-between items-center pt-4 border-t border-white/5">
                                <span className="text-xs text-gray-500">{t.durationMin} mins</span>
                                <button 
                                    onClick={() => bookTreatment(t)}
                                    className="text-xs uppercase tracking-widest border border-white/10 px-4 py-2 rounded hover:bg-luxury-gold hover:text-black hover:border-luxury-gold transition-colors"
                                >
                                    Book {locationTier === LocationTier.STANDARD ? 'Standard' : locationTier === LocationTier.IN_ROOM ? 'In-Room' : 'Private'}
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {activeSection === 'mind' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {TECH_AMENITIES.map(tech => (
                    <div key={tech.id} className="bg-luxury-charcoal rounded-xl overflow-hidden border border-white/5 hover:border-blue-400/30 transition-all group flex flex-col shadow-lg">
                        <div className="h-48 overflow-hidden relative">
