                                        <div className="flex items-center justify-end gap-2">
                                            <button onClick={() => updateInventory(item.id, -1)} className="w-8 h-8 rounded bg-white/10 hover:bg-red-500/20 hover:text-red-500 flex items-center justify-center">-</button>
                                            <button onClick={() => updateInventory(item.id, 1)} className="w-8 h-8 rounded bg-white/10 hover:bg-green-500/20 hover:text-green-500 flex items-center justify-center">+</button>
