            {['overview', 'reports', 'inventory', 'team'].map(tab => (
                <button
                    key={tab}
                    onClick={() => setActiveTab(tab as any)}
                    className={`px-4 md:px-6 py-2 rounded-md text-xs md:text-sm uppercase tracking-wider transition-all whitespace-nowrap ${
