                        <div 
                            key={room.id}
                            onClick={() => toggleRoomStatus(room.id)}
                            className={`p-6 rounded-xl border cursor-pointer transition-all text-center ${
                                room.status === 'Available' ? 'bg-green-500/10 border-green-500/30' :
