                                    onClick={() => markTaskComplete(order.txId, order.id)}
                                    className="w-full py-3 bg-white/10 hover:bg-green-500 hover:text-white text-gray-300 rounded font-bold uppercase tracking-widest transition-colors"
                                >
                                    Mark Ready
                                </button>
                            </div>
                        ))
                    )}
                </div>
            ) : (
                <div className="bg-luxury-charcoal rounded-xl border border-white/5 overflow-hidden">
                    <div className="p-4 bg-black/20 flex justify-end">
                        <button onClick={() => { setEditingItem({}); setIsEditModalOpen(true); }} className="bg-luxury-gold text-black px-4 py-2 rounded font-bold hover:bg-white transition-colors">+ New Dish</button>
                    </div>
                    <table className="w-full text-left text-sm text-gray-400">
