        const statuses = ['Available', 'Occupied', 'Cleaning'];
        setRooms(prev => prev.map(r => {
            if (r.id === id) {
                const nextIdx = (statuses.indexOf(r.status) + 1) % statuses.length;
                return { ...r, status: statuses[nextIdx] };
            }
            return r;
        }));
    };

    return (
        <div className="space-y-8 animate-fade-in">
