const AdminDashboards: React.FC<DashboardProps> = (props) => {
  const { user, onLogout } = props;

  // Determine which specific dashboard to render based on role
  const renderDashboard = () => {
      switch(user.role) {
          case UserRole.SUPER_ADMIN: return <SuperAdminView {...props} />;
          case UserRole.HOTEL_ADMIN: return <HotelAdminView {...props} />;
          case UserRole.CHEF: return <ChefDashboard {...props} />;
          case UserRole.NUTRITIONIST: return <NutritionistDashboard {...props} />;
          case UserRole.TRAINER: return <TrainerDashboard {...props} />;
          case UserRole.SPA_MANAGER: return <SpaDashboard {...props} />;
          case UserRole.CONCIERGE: return <ConciergeDashboard {...props} />;
          default: return <div className="p-8 text-center text-red-500">Access Restricted</div>;
      }
  };

  return (
    <div className="min-h-screen bg-luxury-black font-sans text-luxury-cream p-4 md:p-8 overflow-x-hidden">
        <div className="max-w-7xl mx-auto">
            {/* Top Bar */}
            <div className="flex flex-col md:flex-row justify-between md:items-center mb-8 pb-4 border-b border-white/10 gap-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-luxury-gold rounded flex items-center justify-center text-black font-bold">
                        {user.role === UserRole.SUPER_ADMIN ? 'S' : user.role.charAt(0)}
                    </div>
                    <div>
                        <p className="text-xs uppercase text-gray-500 tracking-widest">Signed in as</p>
                        <p className="font-bold text-white">{user.name} <span className="text-xs bg-white/10 px-2 py-0.5 rounded text-gray-400 font-normal ml-2">{user.role}</span></p>
                    </div>
                </div>
                <button 
                    onClick={onLogout}
                    className="text-xs uppercase tracking-widest text-red-400 hover:text-red-300 border border-red-500/30 px-4 py-2 rounded hover:bg-red-500/10 transition-colors w-full md:w-auto"
                >
                    Logout
                </button>
            </div>

            {renderDashboard()}
        </div>
    </div>
  );
};

export default AdminDashboards;

