// --- 5. CONCIERGE DASHBOARD ---
const ConciergeDashboard: React.FC<DashboardProps> = () => {
    const [techInventory, setTechInventory] = useState(TECH_AMENITIES.map(t => ({ ...t, status: 'Available' })));
    const [tours, setTours] = useState([
        { id: 1, name: 'Sunset Dhow Cruise', slots: 4, time: '17:00' },
        { id: 2, name: 'Spice Farm Tour', slots: 8, time: '09:00' },
        { id: 3, name: 'Stone Town Walk', slots: 12, time: '14:00' }
    ]);

    // Modal State for adding Tours
    const [isTourModalOpen, setIsTourModalOpen] = useState(false);
    const [newTour, setNewTour] = useState({ name: '', time: '', slots: 10 });

    const toggleTechStatus = (id: string) => {
        setTechInventory(prev => prev.map(t => t.id === id ? { ...t, status: t.status === 'Available' ? 'Rented' : 'Available' } : t));
    };

    const handleAddTour = () => {
        if (!newTour.name || !newTour.time) return;
        setTours(prev => [...prev, { id: Date.now(), ...newTour } as any]);
        setIsTourModalOpen(false);
        setNewTour({ name: '', time: '', slots: 10 });
    };

    const handleDeleteTour = (id: number) => {
        if(window.confirm('Cancel this excursion?')) {
            setTours(prev => prev.filter(t => t.id !== id));
        }
    };

    return (
        <div className="space-y-8 animate-fade-in relative">
            <header className="border-b border-white/10 pb-4">
                <h2 className="font-serif text-3xl text-luxury-gold">Concierge & Experiences</h2>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Mental Wellness Tech */}
                <div className="bg-luxury-charcoal p-6 rounded-xl border border-white/5">
                    <h3 className="text-xl font-bold text-white mb-6">Wellness Rentals (Inventory)</h3>
                    <div className="space-y-4">
                        {techInventory.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-white/5 p-4 rounded-lg">
                                <div className="flex items-center gap-4">
                                    <img src={item.imageUrl} className="w-12 h-12 rounded object-cover" alt="" />
                                    <div>
                                        <p className="text-white font-bold">{item.name}</p>
                                        <p className="text-xs text-gray-400 font-mono">${item.pricePerDay}/day</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => toggleTechStatus(item.id)}
                                    className={`px-3 py-1 rounded text-xs font-bold uppercase w-24 transition-colors ${
                                        item.status === 'Available' 
                                        ? 'bg-green-500/20 text-green-500 border border-green-500/50 hover:bg-green-500/30' 
                                        : 'bg-blue-500/20 text-blue-500 border border-blue-500/50 hover:bg-blue-500/30'
                                    }`}
                                >
                                    {item.status}
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Excursions */}
                <div className="bg-luxury-charcoal p-6 rounded-xl border border-white/5">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-white">Daily Excursions</h3>
                        <button 
                            onClick={() => setIsTourModalOpen(true)}
                            className="text-xs bg-luxury-gold text-black font-bold px-3 py-1.5 rounded hover:bg-white transition-colors"
                        >
                            + Add Tour
                        </button>
                    </div>
                    <div className="space-y-3">
                        {tours.length === 0 ? (
                            <p className="text-gray-500 text-sm italic">No active tours scheduled.</p>
                        ) : (
                            tours.map(tour => (
                                <div key={tour.id} className="border-l-2 border-luxury-gold pl-4 py-3 bg-white/5 rounded-r-lg transition-colors flex justify-between items-center group">
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <h4 className="font-bold text-white">{tour.name}</h4>
                                            <span className="font-mono text-luxury-gold text-xs bg-black/40 px-2 py-0.5 rounded">{tour.time}</span>
                                        </div>
                                        <p className="text-xs text-gray-400 mt-1">{tour.slots} spots remaining</p>
                                    </div>
                                    <button onClick={() => handleDeleteTour(tour.id)} className="text-red-500 opacity-0 group-hover:opacity-100 transition-opacity p-2 hover:bg-red-500/10 rounded">🗑</button>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>

            {/* ADD TOUR MODAL */}
            {isTourModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-[#1c1c1e] w-full max-w-sm p-6 rounded-2xl border border-white/10 shadow-2xl">
                        <h3 className="text-xl font-bold text-white mb-4">Add New Excursion</h3>
                        <div className="space-y-4">
                            <div>
                                <label className="text-xs text-gray-500 uppercase font-bold">Tour Name</label>
                                <input 
                                    type="text" 
                                    className="w-full bg-white/5 border border-white/10 rounded p-3 text-white focus:border-luxury-gold outline-none mt-1"
                                    value={newTour.name}
                                    onChange={(e) => setNewTour({...newTour, name: e.target.value})}
                                    placeholder="e.g. Blue Lagoon Snorkeling"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs text-gray-500 uppercase font-bold">Time</label>
                                    <input 
