const SuperAdminView: React.FC<DashboardProps> = () => {
  const [activeAdminTab, setActiveAdminTab] = useState<'tenants' | 'packages'>('tenants');
  const [tenants, setTenants] = useState<Tenant[]>(() => { try { const saved = localStorage.getItem('shee_tenants'); return saved ? JSON.parse(saved) : INITIAL_TENANTS; } catch (e) { return INITIAL_TENANTS; }});
  const [packages, setPackages] = useState<SubscriptionPackage[]>(INITIAL_PACKAGES);
  const [selectedTenant, setSelectedTenant] = useState<Tenant | null>(null);
  const [detailTab, setDetailTab] = useState<'dashboard' | 'financials' | 'team' | 'settings'>('dashboard');

  // Modals
  const [tenantModalOpen, setTenantModalOpen] = useState(false);
  const [packageModalOpen, setPackageModalOpen] = useState(false);
  const [editingTenant, setEditingTenant] = useState<Partial<Tenant> | null>(null);
  const [editingPackage, setEditingPackage] = useState<Partial<SubscriptionPackage> | null>(null);

  useEffect(() => { localStorage.setItem('shee_tenants', JSON.stringify(tenants)); }, [tenants]);

  const totalSystemRevenue = tenants.reduce((acc, t) => acc + t.totalRevenue, 0);
  const totalCommissionRevenue = tenants.reduce((acc, t) => acc + (t.totalRevenue * (t.commissionRate / 100)), 0);
  const activeTenants = tenants.filter(t => t.status === 'Active').length;

  const handleSaveTenant = () => {
      if (!editingTenant?.name || !editingTenant?.location) return;
      if (editingTenant.id) {
          setTenants(prev => prev.map(t => t.id === editingTenant.id ? { ...t, ...editingTenant } as Tenant : t));
          if(selectedTenant?.id === editingTenant.id) setSelectedTenant({ ...selectedTenant, ...editingTenant } as Tenant);
      } else {
          const newTenant: Tenant = {
              id: `T-${Date.now().toString().slice(-4)}`,
              name: editingTenant.name,
              location: editingTenant.location,
              plan: editingTenant.plan || 'Gold',
              status: 'Active',
              commissionRate: 10,
              totalRevenue: 0,
              features: { nutrition: true, fitness: true, spa: true, concierge: true },
              joinedDate: new Date().toISOString()
          };
          setTenants(prev => [newTenant, ...prev]);
      }
      setTenantModalOpen(false);
      setEditingTenant(null);
  };

  const handleDeleteTenant = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (window.confirm('Delete this tenant?')) {
          setTenants(prev => prev.filter(t => t.id !== id));
          if(selectedTenant?.id === id) setSelectedTenant(null);
      }
  };

  const handleSavePackage = () => {
      if (!editingPackage?.name || !editingPackage?.price) return;
      if (editingPackage.id) {
          setPackages(prev => prev.map(p => p.id === editingPackage.id ? { ...p, ...editingPackage } as SubscriptionPackage : p));
      } else {
          setPackages(prev => [...prev, { ...editingPackage, id: `pkg-${Date.now()}`, features: { nutrition: true, fitness: true, spa: true, concierge: true } } as SubscriptionPackage]);
      }
      setPackageModalOpen(false);
      setEditingPackage(null);
  };

  const handleDeletePackage = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (window.confirm('Delete this package?')) setPackages(prev => prev.filter(p => p.id !== id));
  };

  return (
      <div className="space-y-8 animate-fade-in relative">
          <header className="mb-8 flex flex-col md:flex-row justify-between items-start md:items-end">
            <div className="border-l-4 border-luxury-gold pl-4">
                <h2 className="font-serif text-2xl md:text-3xl text-white">SaaS Master Controller</h2>
                <p className="text-gray-400 text-sm md:text-base">System Owner & Multi-Tenant Management</p>
            </div>
            <div className="flex bg-white/5 p-1 rounded-lg mt-4 md:mt-0">
                <button onClick={() => setActiveAdminTab('tenants')} className={`px-4 py-2 rounded text-sm font-bold ${activeAdminTab === 'tenants' ? 'bg-luxury-gold text-black' : 'text-gray-400'}`}>Tenants</button>
                <button onClick={() => setActiveAdminTab('packages')} className={`px-4 py-2 rounded text-sm font-bold ${activeAdminTab === 'packages' ? 'bg-luxury-gold text-black' : 'text-gray-400'}`}>Packages</button>
            </div>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <StatCard label="Total GMV" value={`$${totalSystemRevenue.toLocaleString()}`} color="text-white" />
            <StatCard label="Commission" value={`$${totalCommissionRevenue.toLocaleString(undefined, { maximumFractionDigits: 0 })}`} />
            <StatCard label="Active Properties" value={activeTenants.toString()} color="text-green-500" />
            <StatCard label="System Health" value="100%" color="text-blue-400" />
          </div>

          {activeAdminTab === 'tenants' && (
              <div className="flex flex-col xl:flex-row gap-8 min-h-[600px]">
                  <div className="xl:w-1/3 bg-luxury-charcoal rounded-xl border border-white/5 overflow-hidden flex flex-col">
                      <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/20">
                          <h3 className="text-white font-bold">Properties</h3>
                          <button onClick={() => { setEditingTenant({}); setTenantModalOpen(true); }} className="text-xs bg-luxury-gold text-black px-3 py-1.5 rounded font-bold">+ New</button>
                      </div>
                      <div className="overflow-y-auto flex-1">
                          {tenants.map(t => (
                              <div key={t.id} onClick={() => setSelectedTenant(t)} className={`p-4 border-b border-white/5 cursor-pointer hover:bg-white/5 transition-colors ${selectedTenant?.id === t.id ? 'bg-luxury-gold/10 border-l-2 border-luxury-gold' : ''}`}>
                                  <div className="flex justify-between items-start">
                                      <h4 className={`font-bold ${selectedTenant?.id === t.id ? 'text-luxury-gold' : 'text-white'}`}>{t.name}</h4>
                                      <span className={`text-[10px] px-1.5 py-0.5 rounded border ${t.status === 'Active' ? 'text-green-500 border-green-500/20' : 'text-red-500 border-red-500/20'}`}>{t.status}</span>
                                  </div>
                                  <p className="text-xs text-gray-500 mt-1">{t.location} • {t.plan}</p>
                                  <div className="flex justify-between items-center mt-3">
                                      <span className="text-xs font-mono text-gray-300">${t.totalRevenue.toLocaleString()}</span>
                                      <div className="flex gap-2">
                                          <button onClick={(e) => { e.stopPropagation(); setEditingTenant(t); setTenantModalOpen(true); }} className="text-gray-400 hover:text-white">✎</button>
                                          <button onClick={(e) => handleDeleteTenant(t.id, e)} className="text-red-500 hover:text-red-300">🗑</button>
                                      </div>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>

                  <div className="xl:w-2/3 bg-[#121212] rounded-xl border border-luxury-gold/30 flex flex-col relative overflow-hidden">
                      {selectedTenant ? (
                          <>
                            <div className="p-6 border-b border-white/10 bg-black/20 flex justify-between items-center">
                                <div>
                                    <h3 className="text-2xl text-white font-serif">{selectedTenant.name}</h3>
                                    <p className="text-xs text-gray-400">ID: {selectedTenant.id}</p>
                                </div>
                                <div className="flex gap-2">
                                    {['dashboard', 'financials', 'team', 'settings'].map(t => (
                                        <button key={t} onClick={() => setDetailTab(t as any)} className={`px-4 py-1.5 rounded text-xs uppercase font-bold ${detailTab === t ? 'bg-luxury-gold text-black' : 'bg-white/5 text-gray-400'}`}>{t}</button>
                                    ))}
                                </div>
                            </div>
                            <div className="p-6 flex-1 overflow-y-auto">
                                {detailTab === 'dashboard' && (
                                    <div className="space-y-6">
                                        <div className="grid grid-cols-3 gap-4">
                                            <div className="bg-luxury-charcoal p-4 rounded border border-white/5"><p className="text-xs text-gray-500 uppercase">Rev</p><p className="text-xl text-white font-mono">${selectedTenant.totalRevenue.toLocaleString()}</p></div>
                                            <div className="bg-luxury-charcoal p-4 rounded border border-white/5"><p className="text-xs text-gray-500 uppercase">Comm</p><p className="text-xl text-luxury-gold font-mono">${(selectedTenant.totalRevenue * (selectedTenant.commissionRate/100)).toFixed(0)}</p></div>
                                            <div className="bg-luxury-charcoal p-4 rounded border border-white/5"><p className="text-xs text-gray-500 uppercase">Rate</p><p className="text-xl text-white font-mono">{selectedTenant.commissionRate}%</p></div>
                                        </div>
                                        <div className="bg-white/5 rounded-xl p-6 border border-white/5">
                                            <h4 className="text-sm font-bold text-white mb-4 uppercase tracking-widest">Recent Activity Log</h4>
                                            <div className="space-y-0">
                                                {getMockActivity(selectedTenant.id).map((log, idx) => (
                                                    <div key={idx} className="flex justify-between items-center py-3 border-b border-white/5 last:border-0 hover:bg-white/5 px-2 -mx-2 rounded transition-colors">
                                                        <div>
                                                            <p className={`text-sm font-bold ${log.isAlert ? 'text-red-400' : 'text-gray-300'}`}>{log.action}</p>
                                                            <p className="text-[10px] text-gray-500">{log.time}</p>
                                                        </div>
                                                        <span className={`text-xs font-mono font-bold ${log.val.startsWith('+') ? 'text-green-500' : log.val.startsWith('-') ? 'text-luxury-gold' : 'text-red-400'}`}>{log.val}</span>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}
                                {detailTab === 'team' && (
                                    <div className="grid grid-cols-2 gap-4">
                                        {getMockStaff(selectedTenant.id).map((staff, i) => (
                                            <div key={i} className="bg-white/5 p-4 rounded flex justify-between items-center">
                                                <div><p className="text-white font-bold">{staff.name}</p><p className="text-xs text-gray-500">{staff.role}</p></div>
                                                <span className="text-[10px] bg-green-500/20 text-green-500 px-2 py-1 rounded">{staff.status}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                {detailTab === 'settings' && (
                                    <div className="space-y-4">
                                        <div className="p-4 bg-white/5 rounded"><p className="text-sm text-gray-300 mb-2">Commission Rate</p><input type="number" className="bg-black border border-white/10 p-2 rounded text-white w-full" value={selectedTenant.commissionRate} disabled /></div>
                                    </div>
                                )}
                            </div>
                          </>
                      ) : (
                          <div className="flex-1 flex items-center justify-center text-gray-500">Select a tenant to view details</div>
                      )}
                  </div>
              </div>
          )}

          {activeAdminTab === 'packages' && (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {packages.map(pkg => (
                      <div key={pkg.id} className="bg-luxury-charcoal p-6 rounded-xl border border-white/5 hover:border-luxury-gold/50 transition-all group relative">
                          {pkg.recommended && <div className="absolute top-0 right-0 bg-luxury-gold text-black text-[10px] font-bold px-3 py-1 rounded-bl">RECOMMENDED</div>}
                          <h3 className="text-xl font-bold text-white mb-2">{pkg.name}</h3>
                          <p className="text-3xl font-serif text-luxury-gold mb-4">${pkg.price}<span className="text-sm text-gray-500">/mo</span></p>
                          <p className="text-sm text-gray-400 mb-6 h-10">{pkg.description}</p>
                          <div className="space-y-2 mb-6">
                              {Object.entries(pkg.features).map(([k,v]) => (
                                  <div key={k} className={`text-xs flex items-center gap-2 ${v ? 'text-gray-300' : 'text-gray-600'}`}>
                                      <span>{v ? '✓' : '✕'}</span> <span className="uppercase">{k}</span>
                                  </div>
                              ))}
                          </div>
                          <div className="flex gap-2">
                              <button onClick={() => { setEditingPackage(pkg); setPackageModalOpen(true); }} className="flex-1 py-2 bg-white/5 hover:bg-white/10 text-white rounded text-xs font-bold uppercase">Edit</button>
                              <button onClick={(e) => handleDeletePackage(pkg.id, e)} className="px-3 bg-red-500/10 text-red-500 rounded hover:bg-red-500/20">🗑</button>
                          </div>
                      </div>
                  ))}
                  <button onClick={() => { setEditingPackage({}); setPackageModalOpen(true); }} className="border-2 border-dashed border-white/10 rounded-xl flex items-center justify-center text-gray-500 hover:text-white hover:border-white/30 transition-all min-h-[300px]">
                      + New Package
                  </button>
              </div>
          )}

          {tenantModalOpen && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
                  <div className="bg-luxury-charcoal w-full max-w-md p-8 rounded-2xl border border-white/10">
                      <h3 className="text-xl font-bold text-white mb-6">Manage Tenant</h3>
                      <input className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" placeholder="Property Name" value={editingTenant?.name || ''} onChange={e => setEditingTenant(prev => ({...prev, name: e.target.value}))} />
                      <input className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" placeholder="Location" value={editingTenant?.location || ''} onChange={e => setEditingTenant(prev => ({...prev, location: e.target.value}))} />
                      <select className="w-full bg-white/5 border border-white/10 p-3 rounded mb-6 text-white" value={editingTenant?.plan || 'Gold'} onChange={e => setEditingTenant(prev => ({...prev, plan: e.target.value}))}>
                          {packages.map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                      </select>
                      <div className="flex gap-4">
                          <button onClick={() => setTenantModalOpen(false)} className="flex-1 py-3 border border-gray-600 rounded text-gray-400">Cancel</button>
                          <button onClick={handleSaveTenant} className="flex-1 py-3 bg-luxury-gold text-black font-bold rounded">Save</button>
                      </div>
                  </div>
              </div>
          )}

          {packageModalOpen && (
              <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
                  <div className="bg-luxury-charcoal w-full max-w-md p-8 rounded-2xl border border-white/10">
                      <h3 className="text-xl font-bold text-white mb-6">Manage Package</h3>
                      <input className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" placeholder="Package Name" value={editingPackage?.name || ''} onChange={e => setEditingPackage(prev => ({...prev, name: e.target.value}))} />
                      <input className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" type="number" placeholder="Price" value={editingPackage?.price || ''} onChange={e => setEditingPackage(prev => ({...prev, price: Number(e.target.value)}))} />
                      <div className="flex gap-4">
                          <button onClick={() => setPackageModalOpen(false)} className="flex-1 py-3 border border-gray-600 rounded text-gray-400">Cancel</button>
                          <button onClick={handleSavePackage} className="flex-1 py-3 bg-luxury-gold text-black font-bold rounded">Save</button>
                      </div>
                  </div>
              </div>
          )}
      </div>
  );
};

// --- HOTEL ADMIN ---
const HotelAdminView: React.FC<DashboardProps> = ({ history, inventory, setInventory, commissionRate }) => {
    const [activeTab, setActiveTab] = useState<'overview' | 'reports' | 'inventory' | 'team'>('overview');
    const [staffList, setStaffList] = useState<StaffMember[]>(MOCK_STAFF);
    const [staffModalOpen, setStaffModalOpen] = useState(false);
    const [editingStaff, setEditingStaff] = useState<Partial<StaffMember> | null>(null);
    const [inventoryModalOpen, setInventoryModalOpen] = useState(false);
    const [editingInventory, setEditingInventory] = useState<Partial<InventoryItem> | null>(null);
    const [inventorySearch, setInventorySearch] = useState('');
    const [reportRange, setReportRange] = useState<'all' | '7days' | '30days'>('all');
    const [reportType, setReportType] = useState<'all' | 'Food' | 'Service' | 'Room'>('all');

    const totalRevenue = history.reduce((sum, t) => sum + t.total, 0);
    const hotelRevenue = totalRevenue * ((100 - commissionRate) / 100);

    const filteredHistory = useMemo(() => {
        let data = history;
        const now = new Date();
        if (reportRange === '7days') {
            const past = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            data = data.filter(t => new Date(t.date) >= past);
        } else if (reportRange === '30days') {
            const past = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            data = data.filter(t => new Date(t.date) >= past);
        }
        return data;
    }, [history, reportRange]);

    const reportStats = useMemo(() => {
        let revenue = 0;
        let count = 0;
        filteredHistory.forEach(tx => {
            tx.items.forEach(item => {
                if (reportType === 'all' || item.type === reportType) {
                    revenue += item.price;
                    count++;
                }
            });
        });
        return { revenue, count };
    }, [filteredHistory, reportType]);

    const handleSaveStaff = () => {
        if (!editingStaff?.name || !editingStaff?.role) return;
        if (editingStaff.id) {
            setStaffList(prev => prev.map(s => s.id === editingStaff.id ? { ...s, ...editingStaff } as StaffMember : s));
        } else {
            const newStaff: StaffMember = {
                id: `st-${Date.now()}`,
                name: editingStaff.name,
                role: editingStaff.role,
                email: editingStaff.email || '',
                phone: editingStaff.phone || '',
                department: editingStaff.department || 'General',
                status: 'Offline',
                shift: 'Morning'
            };
            setStaffList(prev => [...prev, newStaff]);
        }
        setStaffModalOpen(false);
        setEditingStaff(null);
    };

    const handleDeleteStaff = (id: string) => {
        if (window.confirm('Are you sure you want to remove this employee?')) {
            setStaffList(prev => prev.filter(s => s.id !== id));
        }
    };

    const handleSaveInventory = () => {
        if (!editingInventory?.name || !editingInventory?.category) return;
        if (editingInventory.id) {
            setInventory(prev => prev.map(i => i.id === editingInventory.id ? { ...i, ...editingInventory } as InventoryItem : i));
        } else {
            const newItem: InventoryItem = {
                id: `inv-${Date.now()}`,
                name: editingInventory.name,
                category: editingInventory.category,
                quantity: editingInventory.quantity || 0,
                threshold: editingInventory.threshold || 10,
                unit: editingInventory.unit || 'pcs'
            };
            setInventory(prev => [...prev, newItem]);
        }
        setInventoryModalOpen(false);
        setEditingInventory(null);
    };

    const handleDeleteInventory = (id: string) => {
        if (window.confirm('Delete this item from inventory?')) {
            setInventory(prev => prev.filter(i => i.id !== id));
        }
    };

    const filteredInventory = inventory.filter(item => 
        item.name.toLowerCase().includes(inventorySearch.toLowerCase()) || 
        item.category.toLowerCase().includes(inventorySearch.toLowerCase())
    );

    return (
      <div className="space-y-8 animate-fade-in">
        <header className="mb-8 flex flex-col md:flex-row justify-between md:items-end gap-4">
          <div>
              <h2 className="font-serif text-2xl md:text-3xl text-luxury-gold">Property Management</h2>
              <p className="text-gray-400">SmartGuest Resort - Zanzibar</p>
          </div>
          <div className="flex bg-luxury-charcoal p-1 rounded-lg border border-white/5 overflow-x-auto">
              {['overview', 'reports', 'inventory', 'team'].map(tab => (
                  <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 md:px-6 py-2 rounded-md text-xs md:text-sm uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === tab ? 'bg-luxury-gold text-black font-bold' : 'text-gray-400 hover:text-white'}`}>
                      {tab}
                  </button>
              ))}
          </div>
        </header>

        {activeTab === 'overview' && (
            <div className="space-y-8 animate-fade-in">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
