// --- 1. CHEF DASHBOARD ---
const ChefDashboard: React.FC<DashboardProps> = ({ history, markTaskComplete }) => {
    const [view, setView] = useState<'orders' | 'menu'>('orders');
    const [menu, setMenu] = useState<MenuItem[]>(MENU_ITEMS);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<Partial<MenuItem> | null>(null);

    const pendingOrders = history.flatMap(tx => 
        tx.items.filter(item => item.type === 'Food' && item.status !== 'Completed').map(item => ({...item, txId: tx.id, time: tx.date}))
    );

    const handleSaveMenu = () => {
        if(!editingItem?.name) return;
        if(editingItem.id) {
            setMenu(prev => prev.map(i => i.id === editingItem.id ? {...i, ...editingItem} as MenuItem : i));
        } else {
            setMenu(prev => [...prev, { ...editingItem, id: `dish-${Date.now()}`, category: 'Main', tags: [] } as MenuItem]);
        }
        setIsEditModalOpen(false);
    };

    const handleDeleteMenu = (id: string) => {
        if(window.confirm("Remove this dish from the menu?")) {
            setMenu(prev => prev.filter(i => i.id !== id));
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="flex justify-between items-center pb-4 border-b border-white/10">
                <h2 className="font-serif text-3xl text-luxury-gold">Executive Kitchen</h2>
                <div className="flex bg-white/5 p-1 rounded-lg">
                    <button onClick={() => setView('orders')} className={`px-4 py-2 rounded ${view === 'orders' ? 'bg-luxury-gold text-black font-bold' : 'text-gray-400'}`}>Live Orders ({pendingOrders.length})</button>
                    <button onClick={() => setView('menu')} className={`px-4 py-2 rounded ${view === 'menu' ? 'bg-luxury-gold text-black font-bold' : 'text-gray-400'}`}>Digital Menu</button>
                </div>
            </div>

            {view === 'orders' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {pendingOrders.length === 0 ? (
                        <div className="col-span-full py-20 text-center text-gray-500 opacity-50">
                            <span className="text-6xl">🍳</span><p className="mt-4">Kitchen Clear. No active orders.</p>
                        </div>
                    ) : (
                        pendingOrders.map((order, idx) => (
                            <div key={idx} className="bg-luxury-charcoal p-6 rounded-xl border-l-4 border-orange-500 animate-fade-in shadow-lg">
                                <div className="flex justify-between mb-4">
                                    <span className="bg-orange-500/20 text-orange-500 text-xs font-bold px-2 py-1 rounded uppercase">Cooking</span>
                                    <span className="text-gray-400 text-xs font-mono">{new Date(order.time).toLocaleTimeString()}</span>
                                </div>
                                <h3 className="text-xl font-bold text-white mb-2">{order.name}</h3>
                                {order.details && <p className="text-sm text-luxury-gold mb-4 italic">"{order.details}"</p>}
                                <button 
                                    onClick={() => markTaskComplete(order.txId, order.id)}
                                    className="w-full py-3 bg-white/10 hover:bg-green-500 hover:text-white text-gray-300 rounded font-bold uppercase tracking-widest transition-colors"
                                >
                                    Mark Ready
                                </button>
                            </div>
                        ))
                    )}
                </div>
            ) : (
                <div className="bg-luxury-charcoal rounded-xl border border-white/5 overflow-hidden">
                    <div className="p-4 bg-black/20 flex justify-end">
                        <button onClick={() => { setEditingItem({}); setIsEditModalOpen(true); }} className="bg-luxury-gold text-black px-4 py-2 rounded font-bold hover:bg-white transition-colors">+ New Dish</button>
                    </div>
                    <table className="w-full text-left text-sm text-gray-400">
                        <thead className="bg-white/5 uppercase text-xs"><tr><th className="p-4">Dish</th><th className="p-4">Category</th><th className="p-4">Price</th><th className="p-4 text-right">Actions</th></tr></thead>
                        <tbody className="divide-y divide-white/5">
                            {menu.map(item => (
                                <tr key={item.id} className="hover:bg-white/5">
                                    <td className="p-4 font-bold text-white flex items-center gap-3">
                                        <img src={item.imageUrl} className="w-10 h-10 rounded object-cover" alt="" />
                                        {item.name}
                                    </td>
                                    <td className="p-4">{item.category}</td>
                                    <td className="p-4 text-luxury-gold font-mono">${item.price}</td>
                                    <td className="p-4 text-right">
                                        <button onClick={() => { setEditingItem(item); setIsEditModalOpen(true); }} className="text-gray-400 hover:text-white mr-3">Edit</button>
                                        <button onClick={() => handleDeleteMenu(item.id)} className="text-red-500 hover:text-red-400">Delete</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {isEditModalOpen && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
                    <div className="bg-luxury-charcoal w-full max-w-md p-8 rounded-2xl border border-white/10">
                        <h3 className="text-xl font-bold text-white mb-6">Manage Dish</h3>
                        <input type="text" placeholder="Dish Name" className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" value={editingItem?.name || ''} onChange={e => setEditingItem(prev => ({...prev, name: e.target.value}))} />
                        <input type="number" placeholder="Price" className="w-full bg-white/5 border border-white/10 p-3 rounded mb-4 text-white" value={editingItem?.price || ''} onChange={e => setEditingItem(prev => ({...prev, price: Number(e.target.value)}))} />
                        <textarea placeholder="Description" className="w-full bg-white/5 border border-white/10 p-3 rounded mb-6 text-white" value={editingItem?.description || ''} onChange={e => setEditingItem(prev => ({...prev, description: e.target.value}))} />
                        <div className="flex gap-4">
                            <button onClick={() => setIsEditModalOpen(false)} className="flex-1 py-3 border border-gray-600 rounded text-gray-400">Cancel</button>
                            <button onClick={handleSaveMenu} className="flex-1 py-3 bg-luxury-gold text-black font-bold rounded">Save Dish</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

