                                <button onClick={handleSaveReport} className="bg-luxury-gold text-black px-6 py-3 rounded-lg font-bold hover:bg-white transition-colors">
                                    Save to Log
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center text-gray-500 opacity-50">
                            <span className="text-6xl">🥗</span>
                            <p className="mt-4 font-serif text-xl">Select a guest to view profile & log dietary notes.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

