// --- 4. SPA MANAGER DASHBOARD ---
const SpaDashboard: React.FC<DashboardProps> = () => {
    const [treatments, setTreatments] = useState<SpaTreatment[]>(SPA_TREATMENTS);
    const [rooms, setRooms] = useState([
        { id: 1, name: 'Suite A (Couples)', status: 'Available' },
        { id: 2, name: 'Suite B (Deep Tissue)', status: 'Occupied' },
        { id: 3, name: 'Suite C (Hydro)', status: 'Cleaning' },
        { id: 4, name: 'Suite D (Consult)', status: 'Available' },
    ]);

    const toggleRoomStatus = (id: number) => {
        const statuses = ['Available', 'Occupied', 'Cleaning'];
        setRooms(prev => prev.map(r => {
            if (r.id === id) {
                const nextIdx = (statuses.indexOf(r.status) + 1) % statuses.length;
                return { ...r, status: statuses[nextIdx] };
            }
            return r;
        }));
    };

    return (
        <div className="space-y-8 animate-fade-in">
            <header className="border-b border-white/10 pb-4">
                <h2 className="font-serif text-3xl text-luxury-gold">Spa Management</h2>
            </header>

            {/* Room Status Grid */}
            <div>
                <h3 className="text-xl font-bold text-white mb-4">Treatment Rooms</h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {rooms.map(room => (
                        <div 
                            key={room.id}
                            onClick={() => toggleRoomStatus(room.id)}
                            className={`p-6 rounded-xl border cursor-pointer transition-all text-center ${
                                room.status === 'Available' ? 'bg-green-500/10 border-green-500/30' :
                                room.status === 'Occupied' ? 'bg-red-500/10 border-red-500/30' :
                                'bg-yellow-500/10 border-yellow-500/30'
                            }`}
                        >
                            <div className="text-2xl mb-2">{room.status === 'Available' ? '🟢' : room.status === 'Occupied' ? '🔴' : '🧹'}</div>
                            <p className="text-white font-bold">{room.name}</p>
                            <p className={`text-xs uppercase font-bold mt-2 ${
                                room.status === 'Available' ? 'text-green-500' :
                                room.status === 'Occupied' ? 'text-red-500' :
                                'text-yellow-500'
                            }`}>{room.status}</p>
                        </div>
                    ))}
                </div>
            </div>

            {/* Treatment Menu */}
            <div className="bg-luxury-charcoal rounded-xl border border-white/5 overflow-hidden">
                <div className="p-6 bg-black/20 border-b border-white/10 flex justify-between">
                    <h3 className="text-xl font-bold text-white">Treatment Menu</h3>
                    <button className="text-xs bg-luxury-gold text-black px-3 py-1 rounded font-bold hover:bg-white">+ Add Therapy</button>
                </div>
                <table className="w-full text-left text-sm text-gray-400">
                    <thead className="bg-white/5 uppercase text-xs"><tr><th className="p-4">Therapy</th><th className="p-4">Duration</th><th className="p-4">Price</th><th className="p-4">Tags</th></tr></thead>
                    <tbody className="divide-y divide-white/5">
                        {treatments.map(t => (
                            <tr key={t.id} className="hover:bg-white/5">
                                <td className="p-4 font-bold text-white">{t.name}</td>
                                <td className="p-4">{t.durationMin} min</td>
                                <td className="p-4 text-luxury-gold font-mono">${t.price}</td>
                                <td className="p-4"><span className="text-xs opacity-50">{t.tags.join(', ')}</span></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

// --- 5. CONCIERGE DASHBOARD ---
const ConciergeDashboard: React.FC<DashboardProps> = () => {
    const [techInventory, setTechInventory] = useState(TECH_AMENITIES.map(t => ({ ...t, status: 'Available' })));
    const [tours, setTours] = useState([
        { id: 1, name: 'Sunset Dhow Cruise', slots: 4, time: '17:00' },
        { id: 2, name: 'Spice Farm Tour', slots: 8, time: '09:00' },
        { id: 3, name: 'Stone Town Walk', slots: 12, time: '14:00' }
    ]);

    // Modal State for adding Tours
    const [isTourModalOpen, setIsTourModalOpen] = useState(false);
    const [newTour, setNewTour] = useState({ name: '', time: '', slots: 10 });

    const toggleTechStatus = (id: string) => {
        setTechInventory(prev => prev.map(t => t.id === id ? { ...t, status: t.status === 'Available' ? 'Rented' : 'Available' } : t));
    };

    const handleAddTour = () => {
        if (!newTour.name || !newTour.time) return;
        setTours(prev => [...prev, { id: Date.now(), ...newTour } as any]);
        setIsTourModalOpen(false);
        setNewTour({ name: '', time: '', slots: 10 });
    };

    const handleDeleteTour = (id: number) => {
        if(window.confirm('Cancel this excursion?')) {
            setTours(prev => prev.filter(t => t.id !== id));
        }
    };

    return (
        <div className="space-y-8 animate-fade-in relative">
            <header className="border-b border-white/10 pb-4">
                <h2 className="font-serif text-3xl text-luxury-gold">Concierge & Experiences</h2>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Mental Wellness Tech */}
                <div className="bg-luxury-charcoal p-6 rounded-xl border border-white/5">
                    <h3 className="text-xl font-bold text-white mb-6">Wellness Rentals (Inventory)</h3>
                    <div className="space-y-4">
                        {techInventory.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-white/5 p-4 rounded-lg">
                                <div className="flex items-center gap-4">
                                    <img src={item.imageUrl} className="w-12 h-12 rounded object-cover" alt="" />
                                    <div>
                                        <p className="text-white font-bold">{item.name}</p>
                                        <p className="text-xs text-gray-400 font-mono">${item.pricePerDay}/day</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => toggleTechStatus(item.id)}
                                    className={`px-3 py-1 rounded text-xs font-bold uppercase w-24 transition-colors ${
                                        item.status === 'Available' 
                                        ? 'bg-green-500/20 text-green-500 border border-green-500/50 hover:bg-green-500/30' 
                                        : 'bg-blue-500/20 text-blue-500 border border-blue-500/50 hover:bg-blue-500/30'
                                    }`}
                                >
                                    {item.status}
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Excursions */}
                <div className="bg-luxury-charcoal p-6 rounded-xl border border-white/5">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-white">Daily Excursions</h3>
                        <button 
                            onClick={() => setIsTourModalOpen(true)}
                            className="text-xs bg-luxury-gold text-black font-bold px-3 py-1.5 rounded hover:bg-white transition-colors"
                        >
                            + Add Tour
                        </button>
                    </div>
                    <div className="space-y-3">
                        {tours.length === 0 ? (
                            <p className="text-gray-500 text-sm italic">No active tours scheduled.</p>
                        ) : (
                            tours.map(tour => (
                                <div key={tour.id} className="border-l-2 border-luxury-gold pl-4 py-3 bg-white/5 rounded-r-lg transition-colors flex justify-between items-center group">
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <h4 className="font-bold text-white">{tour.name}</h4>
                                            <span className="font-mono text-luxury-gold text-xs bg-black/40 px-2 py-0.5 rounded">{tour.time}</span>
                                        </div>
                                        <p className="text-xs text-gray-400 mt-1">{tour.slots} spots remaining</p>
                                    </div>
                                    <button onClick={() => handleDeleteTour(tour.id)} className="text-red-500 opacity-0 group-hover:opacity-100 transition-opacity p-2 hover:bg-red-500/10 rounded">🗑</button>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>

            {/* ADD TOUR MODAL */}
            {isTourModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-[#1c1c1e] w-full max-w-sm p-6 rounded-2xl border border-white/10 shadow-2xl">
                        <h3 className="text-xl font-bold text-white mb-4">Add New Excursion</h3>
                        <div className="space-y-4">
                            <div>
                                <label className="text-xs text-gray-500 uppercase font-bold">Tour Name</label>
                                <input 
                                    type="text" 
                                    className="w-full bg-white/5 border border-white/10 rounded p-3 text-white focus:border-luxury-gold outline-none mt-1"
                                    value={newTour.name}
                                    onChange={(e) => setNewTour({...newTour, name: e.target.value})}
                                    placeholder="e.g. Blue Lagoon Snorkeling"
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs text-gray-500 uppercase font-bold">Time</label>
                                    <input 
                                        type="time" 
                                        className="w-full bg-white/5 border border-white/10 rounded p-3 text-white focus:border-luxury-gold outline-none mt-1"
                                        value={newTour.time}
                                        onChange={(e) => setNewTour({...newTour, time: e.target.value})}
                                    />
                                </div>
                                <div>
                                    <label className="text-xs text-gray-500 uppercase font-bold">Slots</label>
                                    <input 
                                        type="number" 
                                        className="w-full bg-white/5 border border-white/10 rounded p-3 text-white focus:border-luxury-gold outline-none mt-1"
                                        value={newTour.slots}
                                        onChange={(e) => setNewTour({...newTour, slots: parseInt(e.target.value)})}
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="flex gap-3 mt-6">
                            <button onClick={() => setIsTourModalOpen(false)} className="flex-1 py-3 border border-gray-600 rounded text-gray-400 hover:text-white">Cancel</button>
                            <button onClick={handleAddTour} className="flex-1 py-3 bg-luxury-gold text-black font-bold rounded hover:bg-white">Save Tour</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

// --- MAIN WRAPPER ---
const AdminDashboards: React.FC<DashboardProps> = (props) => {
  const { user, onLogout } = props;

  // Determine which specific dashboard to render based on role
  const renderDashboard = () => {
      switch(user.role) {
          case UserRole.SUPER_ADMIN: return <SuperAdminView {...props} />;
          case UserRole.HOTEL_ADMIN: return <HotelAdminView {...props} />;
          case UserRole.CHEF: return <ChefDashboard {...props} />;
          case UserRole.NUTRITIONIST: return <NutritionistDashboard {...props} />;
          case UserRole.TRAINER: return <TrainerDashboard {...props} />;
          case UserRole.SPA_MANAGER: return <SpaDashboard {...props} />;
          case UserRole.CONCIERGE: return <ConciergeDashboard {...props} />;
          default: return <div className="p-8 text-center text-red-500">Access Restricted</div>;
      }
  };

  return (
    <div className="min-h-screen bg-luxury-black font-sans text-luxury-cream p-4 md:p-8 overflow-x-hidden">
        <div className="max-w-7xl mx-auto">
            {/* Top Bar */}
            <div className="flex flex-col md:flex-row justify-between md:items-center mb-8 pb-4 border-b border-white/10 gap-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-luxury-gold rounded flex items-center justify-center text-black font-bold">
                        {user.role === UserRole.SUPER_ADMIN ? 'S' : user.role.charAt(0)}
                    </div>
                    <div>
                        <p className="text-xs uppercase text-gray-500 tracking-widest">Signed in as</p>
                        <p className="font-bold text-white">{user.name} <span className="text-xs bg-white/10 px-2 py-0.5 rounded text-gray-400 font-normal ml-2">{user.role}</span></p>
                    </div>
                </div>
                <button 
                    onClick={onLogout}
                    className="text-xs uppercase tracking-widest text-red-400 hover:text-red-300 border border-red-500/30 px-4 py-2 rounded hover:bg-red-500/10 transition-colors w-full md:w-auto"
                >
                    Logout
                </button>
            </div>

            {renderDashboard()}
        </div>
    </div>
  );
};

export default AdminDashboards;
